quests[39339] = { id = 39339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein brüchiger Tiegel", description = "Ich habe Kunden mit einem Bedarf an Alchemistensteinen, aber ich kann sie nicht herstellen, solang ich keinen Tiegel habe.\n\nUm einen neuen Tiegel zu bauen, benötigen wir verschiedene Dinge, zunächst aber ein geeignetes Behältnis. Etwas, das so verstärkt werden kann, dass es dem Atem eines Drachen standhält.\n\nEs gibt da einen Ort in Suramar, den die Legion eingenommen hat. Dort findet Ihr sicherlich etwas, das sich für unsere Zwecke eignet.", sourceObjective = "Bringt den brüchigen Dämonenodemtiegel zu Deucus Valdera in Dalaran.", progress = "Ihr seid doch wohl stark genug, um es mit ein paar Dämonen aufzunehmen?", completion = "Ein wirklich faszinierender Fund! Man hat mir schon früher Bruchstücke davon gebracht, aber noch nie so ein gut erhaltenes Exemplar.\n\nDa kommt ein Haufen Arbeit auf uns zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[39340] = { id = 39340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Beschichtung für den Tiegel", description = "Um diesen Tiegel wieder verwendbar zu machen, muss als Erstes die innere Beschichtung restauriert werden. Dazu benötigen wir einige Materialien, die Ihr selbst sammeln oder bei Euren Abenteurerkollegen erwerben könnt.\n\nTeufelswurz und Yserallinensamen sind vor allem Kräuterkundigen bekannt.\n\nTeufelsbalg ist ein Material aus der Kürschnerei.\n\nUnd das Blut von Sargeras findet sich überall auf den Verheerten Inseln.", sourceObjective = "Sammelt 1 Blut von Sargeras, 1 Teufelsbalg, 2 Teufelswurz und 100 Yserallinensamen.", progress = "Die Restaurierung der Tiegelbeschichtung ist keine leichte Aufgabe, {name}.", completion = "Ihr scheint alles bekommen zu haben, was wir benötigen. Ich brauche nur einen Moment, die Materialien auf die Innenseite aufzubringen.\n\n<Deucus restauriert die innere Beschichtung des Tiegels.>\n\nPerfekt! Der Tiegel ist jetzt fast einsatzbereit.\n\nEs fehlt nur noch ein winziges Detail...", sourceObjectiveStatus = "unverified-source-field" }
quests[39341] = { id = 39341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Dämonengalle", description = "Um die Beschichtung des Tiegels zu veredeln, muss er mit der widerwärtigsten aller Teufelsenergien behandelt werden. Ich hasse es, das sagen zu müssen, aber die effektivste Methode dafür ist, ihn der Galle eines Dämons auszusetzen.\n\nJa, ich sagte Galle eines Dämons. Also, seid Ihr bereit?\n\nIm Verlies der Wächterinnen gibt es solch einen Dämon. Es ist eine Wichtelmutter namens Grimoira. Die Tür zu ihrem Zimmer ist mit einem unsichtbaren Schloss gesichert.\n\nNehmt am besten etwas Skaggldrynk mit und greift darauf zurück, wenn Ihr an der Tür angekommen seid.", sourceObjective = "Stellt einen Skaggldrynk her, geht dann zum Verlies der Wächterinnen und taucht den Tiegel in Grimoiras Galle ein.", completion = "Ihr habt es geschafft! Zugegebenermaßen war ich ein bisschen besorgt um Euer Wohlergehen, aber Ihr habt Euch wieder einmal als sehr kompetent erwiesen.\n\nNachdem also die Beschichtung wiederhergestellt und der Tiegel mit Dämonengalle behandelt wurde, ist er bereit für den Einsatz auf dem Alchemietisch.\n\nGut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[39342] = { id = 39342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis des Schwarzmarktes", description = "Möglicherweise habe ich, was Ihr sucht. Büretten wollt Ihr? Kein alltäglicher Gegenstand.\n\nDafür müsst Ihr mir schon einen angemessenen Gefallen tun. Nichts Besonderes, ich brauche nur ein paar Dinge.\n\nEin silbernes Haar von einem hochrangigen Erzmagier... das Blut eines Titanen und... oh... etwas Wein und Käse.\n\nIch bekomme eben auch mal Appetit auf was Feines...", sourceObjective = "Beschafft ein silbernes Haar von Khadgar, Blut von Sargeras, 5 Flaschen Ingwerwein der Kaldorei und 5 Stücke saftigen Azsunafeta.", progress = "Lasst Euch nicht zu lange Zeit. Wer weiß, wer noch an so wertvollen Büretten Interesse hat.", completion = "Ihr habt das Haar?!\n\n<Fräulein Xiulan lacht hörbar.>\n\nOh, ich wünschte, ich hätte dabei sein können, um seinen Gesichtsausdruck zu sehen. Wie dem auch sei, abgemacht ist abgemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39343] = { id = 39343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Biegsame Glasröhren", description = "Ihr habt ein paar Röhren aus biegsamem Glas gefunden. Grimoira scheint sie verwendet zu haben, um ihren Opfern die Innereien herauszusaugen.\n\nMit ihren magischen Eigenschaften sind sie allerdings perfekt für den Einsatz auf einem fortgeschrittenen Alchemietisch geeignet.", sourceObjective = "Bringt die biegsamen Glasröhren zu Deucus Valdera in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Was habt Ihr denn diesmal für mich, {name}? Oh, das sind aber wirklich wundersame Röhren! Und ich wette, ich weiß, wie man sie sogar noch verbessern kann.\n\nDazu müsst Ihr diese Röhren dem Feueratem eines Drachen aussetzen... und zwar im Lichte des Vollmondes während der Tagundnachtgleiche. Und dann müsst Ihr in den Smaragdgrünen Traum reisen und...\n\nOh, Moment. Diese Röhren sind schon perfekt. Vergesst es einfach.\n\nManchmal lasse ich mich von diesen Abenteuergedanken etwas mitreißen...", sourceObjectiveStatus = "unverified-source-field" }
quests[39344] = { id = 39344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Untergrund", description = "Wir haben jetzt fast die gesamte Ausrüstung wieder zusammen, {name}. Und um wieder Fläschchen herzustellen, müssen wir jede Zutat genau abmessen können.\n\nDafür müssen wir meinen Satz an Büretten wieder vervollständigen. Leider sind Büretten schwer zu bekommen. Allerdings gibt es da eine ganz spezielle Quelle...\n\n<Deucus schaut sich um und gibt zu verstehen, dass Ihr näherkommen sollt.>\n\nIhr müsst dazu sozusagen in den Untergrund gehen. Genauer gesagt, auf den Schwarzmarkt.\n\nSprecht mit Fräulein Xiulan. Und {name}: Diskretion! Sagt... keinen Mucks.", sourceObjective = "Sucht Fräulein Xiulan auf, um ein paar Büretten für Deucus zu beschaffen.", completion = "Wir scheinen uns ja jetzt zu verstehen. Dann wollen wir mal sehen, worauf wir uns einigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[39345] = { id = 39345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalibrierungsexperten", description = "Es wird die Mitarbeit einiger hoch qualifizierter Experten brauchen, um diese Büretten für unterschiedlichste Substanzen zu kalibrieren.\n\nDie Chemikerin Emmara in Unterstadt ist eine alte Freundin von mir und hat mir schon bei ähnlichen Aufgaben geholfen.\n\nDonnerfels riecht zwar wie ein Viehstall, aber Jana Winterhuf ist eine herausragende Alchemistin.\n\nUnd in der Beutebucht muss man zwar seine Geldbörse mit einem Schloss versehen, aber Tryks Gießklar war immer aufrichtig und ehrlich zu mir.", sourceObjective = "Bringt die unkalibrierten Mallorybüretten zum Kalibrieren zu den ausgewiesenen Alchemieexperten.", completion = "Ja, diese Büretten scheinen korrekt kalibriert zu sein.\n\nIch wusste, dass die drei Kollegen makellose Arbeit abliefern würden. Man sollte nie jemanden unterschätzen, der großen Wert auf winzige Details legt, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[39346] = { id = 39346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalibrierungstest", description = "Da Ihr jetzt die Büretten kalibrieren habt lassen, solltet Ihr sie gleich ausprobieren! Und das geht nur, indem man verschiedene Tränke in ausreichender Menge herstellt.\n\nNicht gerade spektakulär, was? Aber die wichtigste Zutat in der Alchemie ist der Fleiß!", sourceObjective = "Testet die Mallorybüretten, indem Ihr verschiedene Tränke herstellt.", progress = "Man kann die Funktionstüchtigkeit von Büretten nur testen, indem man sie verwendet!", completion = "Da habt Ihr aber eine beachtliche Anzahl Tränke hergestellt! Dann kann man wohl davon ausgehen, dass die Büretten funktionieren.\n\nIch werde sie dem Alchemietisch hinzufügen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39347] = { id = 39347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanalisierung unserer Bemühungen", description = "Auch wenn meine Zeit bekanntermaßen ja wertvoller ist als die... aller anderen, muss ich wohl eingreifen und beim Ersetzen meines Sudkatalysators aushelfen.\n\nUnd Ihr werdet dabei eine wichtige Rolle als Kontaktperson zu den Schmieden spielen, {name}. Der Gedanke, Ruß auf mein Gewand zu bekommen, lässt mir nämlich die Nackenhaare zu Berge stehen.\n\nHier ist eine Liste der zu erledigenden Dinge. Ich werde inzwischen den Rest besorgen.", sourceObjective = "Sprecht mit Alard Schmied über die Liste der zu erledigenden Dinge.\n\nBereitgestellter Gegenstand:", completion = "Was ist das denn?\n\n<Während Alard die Liste bis zum Ende durchliest, werden seine Augen immer größer.>\n\nIch glaube, Ihr habt nicht ganz verstanden, wonach Ihr hier fragt, oder? Wenn das alles wirklich benötigt wird, sollten wir lieber anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39348] = { id = 39348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Die Hauptzutat", description = "Die erste Zutat findet Ihr nur im nächsten Reich. Glücklicherweise befindet sich in Sturmheim ein Tor, das dorthin führt.\n\nIn den Hallen der Tapferkeit gibt es einen Sand, der zum Polieren der dortigen Bauwerke Anwendung findet. Man nennt ihn Ewigkeitssand. Davon brauche ich reichlich, denn er wird die Grundlage dieses neuen Glases darstellen.\n\nEs wird auch nicht leicht, mit diesem Material zu arbeiten. Da werde ich etwas brauchen, das meine Ausdauer aufrechterhält, versteht Ihr?", sourceObjective = "Beschafft den Ewigkeitssand aus den Hallen der Tapferkeit (Heroisch), stellt ein Fläschchen der zehntausend Narben her und bringt beide Gegenstände zu Alard nach Dalaran.", progress = "Die Hallen der Tapferkeit müssen ein unglaublicher Anblick sein. Nach Eurer Rückkehr müsst Ihr mir davon berichten.", completion = "Gut gemacht, {name}. Ich fange an, sobald wir alles beisammenhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[39349] = { id = 39349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Schwer, aber hilfreich", description = "Die nächste Zutat auf der Liste verleiht der Mixtur Stärke, zumindest laut Deucus. Ich habe zwar davon gehört, aber noch nie wirklich damit gearbeitet.\n\nMan nennt es Sabelitsulfat. Die Elfen der Rabenwehr benutzen es angeblich in ihrer Schmiedekunst.\n\nSo etwas liegt gewiss nicht einfach nur herum. Ihr werdet tief in die Festung vordringen müssen, um etwas davon zu finden.\n\nUnd da es so schwer ist, brauche ich eventuell eines Eurer Gemische, um etwas stärker zu werden.", sourceObjective = "Besorgt etwas Sabelitsulfat aus der Rabenwehr (Heroisch), stellt ein Fläschchen der zahllosen Armeen her und bringt beide Gegenstände zu Alard in Dalaran.", progress = "Ich hoffe, Deucus irrt sich nicht mit diesen Zutaten. So etwas stelle ich zum ersten Mal her.", completion = "<Alard nimmt Euch den Beutel ab und wirft einen Blick hinein.>\n\nDas ist also das Zeug? Die Gerüchte stimmen schon. Es ist ziemlich schwer.", sourceObjectiveStatus = "unverified-source-field" }
quests[39350] = { id = 39350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Hoffnung in Helheim", description = "Was die letzte Zutat angeht...\n\n<Alard überlegt einen Moment und nickt.>\n\nJa, anders geht es nicht. Für die letzte Zutat werdet Ihr Euch ins Land der Verdammten begeben müssen, nach Helheim.\n\nNun ja, nicht direkt dorthin, aber auf die Fähre, die die Toten über den Seelenschlund befördert. Die letzte Zutat, die wir brauchen, befindet sich möglicherweise auf diesem Boot.\n\nMan nennt sie Dragurstaub. Haltet Ausschau danach.\n\nAußerdem muss man bei der Verarbeitung dieses Reagenzes flink sein. Ich brauche etwas, das meine Reflexe verbessert.", sourceObjective = "Besorgt eine Kiste mit Dragurstaub aus dem Seelenschlund (Heroisch), stellt ein Fläschchen des Siebten Dämons her und bringt beide Gegenstände zu Alard in Dalaran.", progress = "Seid Ihr auf das Boot gelangt? Habt Ihr den Staub gefunden?", completion = "Ihr habt welchen gefunden?\n\n<Alard nimmt die Kiste, öffnet sie und taumelt ob des Gestanks rückwärts.>\n\nOh ja, das ist eindeutig das Richtige. Beim Licht, das stinkt vielleicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39351] = { id = 39351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Tobendes Feuer", description = "Jetzt haben wir alle Zutaten beisammen und brauchen nur noch eines.\n\nMeine Schmieden sind zwar heiß, doch nicht heiß genug, um diese Materialien zu Glas zu verarbeiten. Dafür brauchen wir etwas Heißeres. Die Hitze eines Drachen, um genau zu sein.\n\nIch habe gehört, dass ein Drache in verderbtem Zustand aus dem Smaragdgrünen Traum hervorgegangen ist. Verderbt oder nicht, das Herz eines Drachen brennt heiß genug, um selbst die robustesten Materialien einzuschmelzen.\n\nBringt mir sein Herz, dann bekommt Ihr Euren Katalysator.", sourceObjective = "Begebt Euch in den Smaragdgrünen Alptraum und besorgt Nythendras Herz. Bringt es zu Alard in Dalaran.", progress = "Ich bereite das Gemisch jetzt vor. Sobald Ihr mit dem Herz zurückkehrt, fange ich mit der Fertigung an.", completion = "<Ihr reicht Alard das Herz. Er legt es in seine Schmiede, wo es anfängt, mit weißer Hitze zu brennen.>\n\nVielleicht sollte ich Euch von jetzt an Drachentöter {name} nennen.\n\nSpaß beiseite, ich fange mit dem Schmieden an.", sourceObjectiveStatus = "unverified-source-field" }
quests[39352] = { id = 39352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausschalten der Schildwachen", description = "Ihr habt es geschafft. Seht Ihr das Lager dort? Dort verbergen sich ein paar Schildwachen der Legion, die den Auftrag haben, Sargeras sofort zu benachrichtigen, wenn sein Hündchen Hunger hat oder sich einsam fühlt. Schaltet sie aus.", sourceObjective = "Schaltet die drei Schildwachen aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[39354] = { id = 39354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irrwisch in den Weiden", description = "Irrwische sind die Geister unserer Nachtelfenbrüder, die eins mit dem Wald wurden. Aber ihr Verstand und ihre Sicht der Dinge sind nicht mehr dieselben wie zu ihren Lebzeiten.\n\nIhr solltet eine Verbindung mit diesem kleinen Irrwisch eingehen. Seht durch seine Augen, wenn er zu den verborgenen Teichen reist und Bäume wachsen lässt.", sourceObjective = "Leitet den Irrwisch zu den verborgenen Teichen, um 8 Bäume wachsen zu lassen.", progress = "Hattet Ihr Erfolg?", completion = "Ich danke Euch, Reisender! Ihr habt dem Wald heute wirklich einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39355] = { id = 39355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausstattungsbaupläne: Abgerichtete Haie", description = "Das scheinen Baupläne für Schiffsausrüstung zu sein. Wir sollten sie zu unserer Schiffswerft zurückbringen, um zu sehen, ob sie jemand entziffern kann.", sourceObjective = "Bringt die Pläne zu einem Spezialisten für Marineausstattung in der Werft Eurer Garnison.", progress = "Das sieht mir nach Ausstattungsbauplänen aus!", completion = "Das ist der Bauplan für eine hochmoderne Schiffsausstattung. Anhand dieser Pläne sollte ich die Ausrüstung nachkonstruieren können, sie wird schon bald für Euch bereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[39356] = { id = 39356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausstattungsbaupläne: Hochleistungsnebelleuchten", description = "Das scheinen Baupläne für Schiffsausrüstung zu sein. Wir sollten sie zu unserer Schiffswerft zurückbringen, um zu sehen, ob sie jemand entziffern kann.", sourceObjective = "Bringt die Pläne zu einem Spezialisten für Marineausstattung in der Werft Eurer Garnison.", progress = "Das sieht mir nach Ausstattungsbauplänen aus!", completion = "Das ist der Bauplan für eine hochmoderne Schiffsausstattung. Anhand dieser Pläne sollte ich die Ausrüstung nachkonstruieren können, sie wird schon bald für Euch bereit sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[39357] = { id = 39357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Grove - Vignette: Eileen - TRACKING - twh" }
quests[39358] = { id = 39358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausstattungsbaupläne: Unsinkbar", description = "Das scheinen Baupläne für Schiffsausrüstung zu sein. Wir sollten sie zu unserer Schiffswerft zurückbringen, um zu sehen, ob sie jemand entziffern kann.", sourceObjective = "Bringt die Pläne zu einem Spezialisten für Marineausstattung in der Werft Eurer Garnison.", progress = "Das sieht mir nach Ausstattungsbauplänen aus!", completion = "Das ist der Bauplan für eine hochmoderne Schiffsausstattung. Anhand dieser Pläne sollte ich die Ausrüstung nachkonstruieren können, sie wird schon bald für Euch bereit sein!", sourceObjectiveStatus = "unverified-source-field" }
