quests[39372] = { id = 39372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexe des Waldes", description = "Ihr habt mich vor Kurzem an der Flusswindung gerettet. Das ist der Grund, warum ich Eure Rolle als Abgesandter bei diesem Stamm unterstützte, und auch der einzige Grund, warum Ihr jetzt noch am Leben seid. Ich betrachte damit meine Schuld Euch gegenüber als beglichen.\n\nIhr müsst Euch dem Häuptling der Bluttotems gegenüber beweisen, bevor er mit Euch sprechen wird.\n\nIn diesem Wald befindet sich die Hexe des Waldes, eine Harpyienmutter, die sich erst kürzlich in unserem Territorium niedergelassen hat. Wenn Ihr in der Lage seid, sie zu bezwingen, und ihren Leichnam den Bluttotems präsentiert, gestatten sie Euch vielleicht eine Audienz bei Torok.", sourceObjective = "Bezwingt die Hexe des Waldes.", completion = "Der Bluttotemstamm gestattet es Fremden nicht oft, zu ihnen zu kommen. Selbst nach einer Audienz zu fragen, kann gefährlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[39373] = { id = 39373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federn rupfen", description = "Die Drogbar, aus deren Gewalt Ihr mich befreit habt, waren ungewöhnlich aggressiv. Der Stamm aus den Höhlen hier in der Nähe scheint vom Rest getrennt zu leben, aber das hielt die Bluttotems nicht davon ab, eine präventive Offensive zu starten und einige von ihnen gefangen zu nehmen.\n\nDurch diese Entscheidung blieb der Wald jedoch unbewacht und stand für den Einfall der Harpyien offen. Eure Hilfe beim Dezimieren dieser Hexen würde von Torok nicht unbeachtet bleiben. Bringt einige Federn zurück, um ihren Tod zu beweisen.", sourceObjective = "Sammelt 50 Greisenfedern von Hexenwaldgreisinnen im Hexenwald.", progress = "Eure Größe straft Eure Stärke Lügen, {name}.", completion = "Ich konnte ihr Kreischen bis hierher hören. Nach diesem Sieg und dem Tod der Hexe des Waldes wird Torok bestimmt einwilligen, mit Euch zu sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39374] = { id = 39374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz bei Torok", description = "Ich sollte Euch warnen, dass Torok sehr schnell verärgert ist und Fremde nicht ausstehen kann. Seid auf der Hut.\n\nWir werden eine Audienz in seinem Zelt am Klippenrand ersuchen. Als Abgesandter der Flussmähnen hier befinde ich mich in relativer Sicherheit, doch Euch gegenüber haben sie keinerlei solche Versprechungen gemacht.", sourceObjective = "Sprecht mit Torok Bluttotem.", progress = "Ich hoffe nur, dass die Bluttotems uns nicht einen Kopf kürzer dafür machen, dass wir die Zeit ihres Häuptlings beanspruchen wollen.", completion = "Seltsam, dass er zu dieser Zeit in der Höhle ist... vielleicht ist das ein gutes Zeichen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39375] = { id = 39375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
