quests[39380] = { id = 39380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[39381] = { id = 39381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Stein ins Trollen bringen", description = "Wir sollten diesen Ort verlassen, so lang wir noch Gelegenheit dazu haben. Die Bluttotems versammeln sich bei ihrem Dorf im Norden und ich glaube, dass sie beabsichtigen, meinen Stamm auszurotten.\n\nLasst mich wissen, wann Ihr zum Aufbruch bereit seid, und ich werde uns schnell an einen sicheren Ort bringen.", sourceObjective = "Sprecht mit Navarrogg, um ihn an einem sicheren Ort zu treffen.", completion = "Ihr habt wenig Grund, mir zu trauen. Doch wir haben in den Bluttotems einen gemeinsamen Feind und ich könnte Eure Hilfe gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39382] = { id = 39382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Perrexx der Verderber", description = "Seht Euch um, {class}. Die Verderbnis hat mein Tal heimgesucht. Wenn Malfurion mich braucht, um Ysera die Erwachte zu beschwören, so will ich ihm helfen. Aber zunächst muss ich mein Land von diesen Dämonen befreien.\n\nGleich da vorn ist Perrexx der Verderber. Helft mir, dieses Monster zu töten.\n\nWenn wir Seite an Seite kämpfen, können wir diese Satyrn und ihre Mitstreiter ausmerzen.", sourceObjective = "Tötet Perrexx den Verderber im Mondklauental.", sourceObjectiveStatus = "unverified-source-field" }
quests[39383] = { id = 39383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrlos", description = "Xandris der Ehrlose gehörte zu den Ersten, die ihr Volk verraten und Xavius' Fluch angenommen haben.\n\nWährend des Krieges war er der Anführer der Truppen, die viele meiner besten Freunde umgebracht haben.\n\nAls wir uns das letzte Mal auf dem Schlachtfeld begegneten, ist er geflohen. Helft mir, endlich Rache an dieser widerwärtigen Kreatur zu nehmen.", sourceObjective = "Tötet Xandris den Ehrlosen.", completion = "Xandris hat endlich für seine Verbrechen bezahlt. Aber sein Blut bringt die getöteten Opfer nicht wieder zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[39384] = { id = 39384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Xandris ist erledigt, aber wir müssen uns noch um andere kümmern, um meinen Hain zu retten.\n\nWährend des Krieges war es Kagraxxis ein großes Vergnügen, das Land zu verderben, das er einst seine Heimat nannte.\n\nWenn die anderen Druiden ihm nicht törichterweise Gnade gewährt hätten, hätte ich ihn selbst hingerichtet.\n\nFindet diesen Dämon und lasst ihm Gerechtigkeit widerfahren.\n\nIch muss Euch diese Aufgabe übertragen, denn ich verspüre die Anwesenheit einer noch dunkleren Präsenz... einer Präsenz, die nach meiner persönlichen Aufmerksamkeit verlangt.", sourceObjective = "Tötet Kagraxxis den Verderber.", progress = "Kagraxxis muss sterben.", completion = "Ich danke Euch, {class}.\n\nWenn Ihr nicht gekommen wärt, wäre es aus mit mir gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39385] = { id = 39385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Graumähne", description = "Die gilnearischen Eindringlinge scheinen hochexplosive Sprengmittel mit in die Schlacht gebracht zu haben. Ich vermute, dass sie damit die Mauern am Schreckensflutufer angreifen wollen.\n\nWenn man diese Ladungen an Graumähnes Schiff befestigen könnte, ist sein Angriff auf den Außenposten vielleicht ein für alle Male beendet.", sourceObjective = "Platziert 3 schwere gilnearische Sprengstoffladungen am Rumpf von Graumähnes Schiff und lasst sie aus sicherer Entfernung detonieren.", completion = "Bei der Gnade der Dunklen Fürstin... Ihr habt es geschafft! Ich konnte die Explosion von hier aus sehen. Diesen vernichtenden Schlag kann Graumähne keinesfalls überlebt haben!\n\nIhr habt den Verlassenen einen großen Dienst erwiesen, den wir niemals vergessen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39386] = { id = 39386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Prototyp muss her", description = "Wenn Addie ein ständiges Mitglied der Jagdgruppe werden soll, dann braucht sie spezielle Ausrüstung für jemanden ihrer Größe.\n\nMein Munitionsexperte sollte ein paar Vorschläge haben, welche Waffen am besten für einen Gnom geeignet sind.\n\nSchaut bei seinem Lager vorbei und sagt ihm, dass ich bald einen Prototyp benötige.", sourceObjective = "Sucht Razik Gazbolz am Eisfichtengrat auf.", completion = "Ein Gnomjäger? Soll das ein Witz sein?\n\nSchon gut. Der Boss bekommt, was der Boss haben will. Ich beginne mit der Arbeit an einem Prototyp, sobald ich mein aktuelles Projekt beendet habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[39387] = { id = 39387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Himmel des Hochbergs", description = "Trefft mich am Fuß des Donnertotems, sobald Ihr bereit seid.\n\nEs wäre mir eine Ehre, Euch an meiner Seite zu haben, wenn mein Stamm dem Oberhäuptling erneut die Treue schwört.\n\nGemeinsam stehen wir für den Hochberg!", sourceObjective = "Sprecht mit Lasan Himmelshorn am Fuß von Donnertotem.", progress = "Hattet Ihr Erfolg bei Lasan?", completion = "Die Himmelshörner sind auf unserer Seite? Der Tag ist gerade sehr viel besser geworden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39388] = { id = 39388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weisheit der Mondklaue", description = "Dank unseres schnellen Eingreifens heute konnten wir den Angriff aufhalten und mein Tal retten. Wie gewünscht werde ich mich Malfurion im Hain des Cenarius anschließen.\n\nAber es gibt noch einiges, was ich Euch über die Satyrn erzählen möchte. Diese Informationen werden Euch sehr behilflich sein.\n\nBitte kommt vor der Abreise in meine Höhle.", sourceObjective = "Trefft Thaon Mondklaue in seiner Höhle.", sourceObjectiveStatus = "unverified-source-field" }
quests[39389] = { id = 39389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er giert nach Blut", description = "Blutsteine enthalten eine Menge Macht, die erst erweckt werden kann, wenn der Stein genährt ist.\n\nDer Stein hat jedoch keine Verwendung für Fisch und Küchlein. Er giert nach Blut: je mächtiger, desto besser.\n\nÖstlich von hier plagen Dämonen die Gegend. Ihr müsst meinen Stein mit ihrem Blut nähren, damit ich seine Macht erschließen kann.", sourceObjective = "Nährt den Blutstein mit dem Blut von Dämonen.", completion = "Der Blutstein sieht gesättigt aus. Gute Arbeit! Jetzt ist es an der Zeit für einen Test...", sourceObjectiveStatus = "unverified-source-field" }
quests[39390] = { id = 39390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mysteriöser Text", description = "Ihr habt einen durchnässten Folianten in der Nähe der Gebeine einer riesigen Kreatur gefunden. Das Buch ist in einer Euch unbekannten Sprache verfasst und mit Runen und alchemistischen Symbolen verziert. Vielleicht kann Euch ein anderer Alchemist mehr darüber erzählen.", sourceObjective = "Bringt den runenbeschriebenen Folianten zu Deucus Valdera in Dalaran.", progress = "Ihr habt etwas da unten in Azsuna gefunden, {name}? Zeigt doch mal her. Es kommt nicht so häufig vor, dass etwas Interessantes in meinen kleinen, ruhigen Laden spaziert.", completion = "Also... Das ist wirklich faszinierend! Dieses Buch ist... also, versteht Ihr... es ist offensichtlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[39391] = { id = 39391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Drogbars bester Freund", description = "Ich ziehe Kreaturen der Erde heran, um mich selbst und mein Volk zu beschützen. Als ich gefangen genommen wurde, befahl ich ihnen, zu Haus zu bleiben. Doch sie sind oft ungehorsam und haben wahrscheinlich versucht, mir zu folgen.\n\nWenn das der Fall ist, fürchte ich, könnten die Bluttotems sie eingefangen haben – oder Schlimmeres. Ich wäre Euch sehr dankbar, wenn Ihr sie finden könntet.", sourceObjective = "Findet Navarroggs Haustiere.", completion = "Splitt ist gefallen? Dieses Jüngste meiner Haustiere war mir vermutlich das Liebste... verflucht seien die Bluttotems und ihre Grausamkeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[39392] = { id = 39392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bärenjagd", description = "Es heißt, ein einziges Haar vom Rücken eines Borstenpelzbären wäre scharf genug, um damit den Bart eines Zwergs zu schneiden. Doch wenn das Fell Euch nicht tötet, werden die Klauen es tun.\n\nEinige ungeübtere Jäger sind bereits als Bärenhappen geendet.\n\nBeweist mir, dass Ihr mehr als nur eine Zwischenmahlzeit seid, und bringt mir ein paar dieser Borstenpelze.", sourceObjective = "Sammelt 4 Borstenpelze auf den Feldern von An'she ein.", progress = "Ein paar Borstenpelze sollten mich von Euren Jagdfertigkeiten überzeugen.", completion = "Diese Pelze sind sogar noch schärfer als erwartet. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39393] = { id = 39393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mondklauental" }
quests[39394] = { id = 39394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Litanei der Verdammnis", description = "Euer Verbündeter und ich werden diese Barriere jetzt entfernen, auch wenn es einen Großteil unserer Stärke aufbrauchen wird. Was jenseits der Barriere folgt, wird nicht einfach werden.\n\nGul'dan wird mithilfe der Litanei einen Elementarlord ermächtigt und in den Wahnsinn getrieben haben. Er wird ihn einsetzen, um die Verbindung zwischen den Elementen und Draenor zu zerstören. Wenn Ihr diesen Elementar vernichtet, können wir die Litanei bergen.", sourceObjective = "Lasst Oronok und Euren Verbündeten die Barriere zerstören und haltet dann Gul'dan auf.", completion = "Ihr habt uns alle gerettet. Die Litanei ist beim Tod von Cyrukh in mehrere Fragmente zerfallen. Das bedeutet, dass die Wächter die Splitter in ganz Draenor verbergen können und man sie unmöglich wieder zusammensetzen kann.\n\nDieser große Sieg verschafft uns mehr Zeit, um Gul'dan aufzuhalten, aber mir graut es davor, wenn ich mir vorstelle, was er als nächstes im Schilde führen könnte...", sourceObjectiveStatus = "unverified-source-field" }
quests[39395] = { id = 39395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oronoks Angebot", sourceObjective = "Ich freue mich, dass Ihr mir vertraut habt, {name}. Es ist, als wäre eine große Last von meinen Schultern gefallen.\n\nWegen meiner Rolle in Gul'dans Plan habe ich gegenüber Draenor eine große Schuld auf mich geladen. Meine Söhne werden den Schamanen beim Zusammensetzen und Verstecken der Splitter helfen. Und, wenn Ihr es erlaubt, möchte ich dabei helfen, Gul'dan vom Antlitz dieser Welt zu entfernen.\n\nIch werde Euch dienen,... Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[39397] = { id = 39397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Experience Received" }
