quests[39399] = { id = 39399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Panther Saberon Boss" }
quests[39400] = { id = 39400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Panther Saberon Boss" }
quests[39401] = { id = 39401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschlagen der Konkurrenz", description = "Eine Schlacht entscheidet noch nicht den Krieg, Kommandant.\n\nDas Transportschiff wird nicht lange gegen die Flotte der Eisernen Horde durchhalten können. Wir werden ein weiteres Schiff brauchen. Zu unserem Glück hat uns ein ortsansässiger Schmuggler mit Plänen versorgt, mit denen wir Zerstörer bauen können. Wir sollten sofort einen bauen!", sourceObjective = "Baut einen Zerstörer in Eurer Werft und schickt ihn auf eine Marinemission.", progress = "Wie sieht es mit dem Zerstörer aus?", completion = "Wir sind ihnen geradewegs auf den Leim gegangen, Kommandant. Das werden sie büßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39404] = { id = 39404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschlagen der Konkurrenz", description = "Eine Schlacht entscheidet noch nicht den Krieg, Kommandant.\n\nDas Transportschiff wird nicht lange gegen die Flotte der Eisernen Horde durchhalten können. Wir werden ein weiteres Schiff brauchen. Zu unserem Glück hat uns ein ortsansässiger Schmuggler mit Plänen versorgt, mit denen wir Zerstörer bauen können. Wir sollten sofort einen bauen!", sourceObjective = "Baut einen Zerstörer in Eurer Werft und schickt ihn auf eine Marinemission.", progress = "Wie sieht es mit dem Zerstörer aus?", completion = "Sie haben uns in die Falle gelockt, Kommandant. Dafür räche ich mich!", sourceObjectiveStatus = "unverified-source-field" }
quests[39405] = { id = 39405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichten des Kampfs", description = "Die von der Priesterin mitgeführten Schriftstücke scheinen der erste Teil eines Epos zu sein. Dieses Werk beschreibt das Leben von Ashildir, der alten Königin der Valkyra.\n\nWenn es eine Verbindung zwischen Ashildir und den Schildmaiden hier gibt, könnt Ihr diesen Umstand vielleicht zu Eurem Vorteil nutzen.\n\nInwieweit sie in diese Sache involviert ist, steht wahrscheinlich im übrigen Text.", sourceObjective = "Sammelt 8 Strophen der Ashilvaradichtung von den Priesterinnen von Eyir in Skold-Ashil ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[39406] = { id = 39406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
