quests[39416] = { id = 39416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skoller's Bag o' Squirrel Treats" }
quests[39417] = { id = 39417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raziks Resultate", description = "Hemet erwartet, dass ich ihm Neues über meine Munitionsforschung und -entwicklung berichte.\n\nIhr werdet meinem Boss doch sicherlich gerne sagen, dass meine neueste Kreation einwandfrei funktioniert hat!\n\nIhr findet ihn in seinem Lager in der Nähe der Jagdhütte.", sourceObjective = "Sucht Hemet Nesingwary an seinem Rückzugsort am Hochberg auf.", completion = "Das höre ich gerne, dass Razik Fortschritte mit seinen technischen Spielereien macht.\n\nWenn er doch nur ein Gewehr erfinden könnte, das selbsttätig zielt, dann würden diese Amateure, die das Becken unsicher machen, vielleicht endlich mal ihre Ziele treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39419] = { id = 39419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fluch-tpunkt", description = "Die Harpiyen kämpfen unnachgiebig um die Vorherrschaft im Becken. Sie bauen ihre magischen Fluchsäcke so schnell, wie wir sie vernichten können.\n\nSo lang die Fluchweberin am Leben ist, werden die Himmelshörner nicht in der Lage sein, die Oberhand zu gewinnen. Sie muss aufgehalten werden.", sourceObjective = "Tötet Fluchweberin Akara.", completion = "Ihr habt den Himmelshörnern einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39420] = { id = 39420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xavius Event TRACKING" }
quests[39422] = { id = 39422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werftbericht", description = "Kommandant! Wir erhalten Berichte, dass die Arbeit in der Werft nun in die heiße Phase geht. Würdet Ihr Euch nach Mondsturz begeben und bei Merreck melden? Jedes Schiff, das vom Stapel läuft, erhöht unsere Chancen gegen Gul'dans neue Horde.", sourceObjective = "Kehrt zu Eurer Werft in Mondsturz zurück.", completion = "Auf Euch haben wir gewartet, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[39423] = { id = 39423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werftbericht", description = "Kommandant! Wir erhalten Berichte, dass die Arbeit in der Werft nun in die heiße Phase geht. Würdet Ihr Euch zum Frostwall begeben und bei Rolosh melden? Jedes Schiff, das vom Stapel läuft, erhöht unsere Chancen gegen Gul'dans neue Horde.", sourceObjective = "Kehrt zu Eurer Werft am Frostwall zurück.", completion = "Auf Euch haben wir gewartet, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[39424] = { id = 39424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles!" }
quests[39425] = { id = 39425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelsteinkristall", description = "Ohne meinen Kristallfokus sind meine Kräfte nur schwach. Die, die mich gefangen nahmen, haben ihn mir abgenommen, und ich weiß, wo er sich jetzt befindet.\n\nIch bin mir sicher, dass einer der Teufelstotems ihn hat. Wenn Ihr ihn finden solltet, bringt ihn bitte zu mir zurück.", sourceObjective = "Findet NavarroggsDunkelsteinfokus.", progress = "Auch ohne meinen Kristall habe ich Macht über die Erde, aber mit ihm ist sie stärker.", completion = "Das wird mir helfen, meinen zerstörten Körper zu reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39426] = { id = 39426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutschuld", description = "Ihr habt Euch als ein besserer Verbündeter erwiesen, als es die Bluttotems je waren. Durch meinen Fokuskristall sind meine Wunden verheilt, doch ich fürchte, für Splitt war es bereits zu spät.\n\nTorok und seine Bluttotems werden für das leiden, was sie uns angetan haben. Lasst uns ihnen einen Besuch abstatten, bevor sie einen Angriff gegen die Höhle meines Volks starten können.", sourceObjective = "Bezwingt Torok Bluttotem an Toroks Fels.", progress = "Wir Drogbar sind nicht von Natur aus gewalttätig, trotz unserer Größe. Aber der Bluttotemstamm hat unseren Zorn geweckt und sie werden ihre Schuld mit Blut bezahlen.", completion = "Ihr habt Euch mein Vertrauen verdient. Die Dunkelsteine sind jedoch vor unseren Brüdern, geführt von Dargrul dem Unterkönig, noch nicht sicher. Wir würden uns nur zu gern mit Mayla Hochberg und ihren Tauren gegen ihn verbünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[39427] = { id = 39427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Adlergeists", description = "Dieser Speer ist mit einem Geist namens Ohn'ahra verbunden. Es ist bei uns Tradition, mit ihr zu sprechen und ihren Segen zu erhalten, bevor wir nach dem Speer suchen. Möglicherweise wird sie auch etwas von ihrem Wissen weitergeben.\n\nWenn Ihr mich zur Geisterwachtspitze begleiten wollt, werde ich den Adlergeist herbeirufen und den Segen für den bevorstehen Kampf erflehen.", sourceObjective = "Nehmt den Segen des Adlergeists an der Geisterwachtspitze am Hochberg entgegen.", progress = "Geschafft!", completion = "Wir haben den Adlergeist gerettet und den Segen erhalten. Jetzt bin ich noch zuversichtlicher, dass wir Fangklaue erwischen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[39428] = { id = 39428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyr Line TRACKING" }
quests[39429] = { id = 39429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Hexenlande", description = "Begebt Euch zu Fuß in die Hexenlande und tötet alle Harpyien, die Ihr finden könnt.\n\nMerzt sie aus!\n\nWir werden Euch Luftunterstützung geben und die Beute am Boden halten, wo Ihr sie bezwingen könnt.\n\nZeigt diesen Hexen den Zorn Eures... nun... Eure Wut halt.", sourceObjective = "Tötet 8 Harpyien der Scharrfurien und 6 Loyalisten der Himmelsschnauzer in den Hexenlanden.", progress = "Es ist schon viele Jahre her, dass wir mit einer Kampftruppe in die Hexenlande vordringen mussten.", completion = "Haha! Ihr seid mit den Federn Eurer Feinde bedeckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[39430] = { id = 39430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scherbenkleister", description = "Dieses Mischfläschchen scheint keinen großen Schaden genommen zu haben. Ich glaube, dass man es reparieren kann.\n\nGlasreparaturen sind nicht meine Stärke, aber ich kenne da jemanden: einen Tauren namens Barm Steinbrecher. Er ist eigentlich Schmied, aber wer ihn kennt, hält ihn für einen geborenen Glasbläser.\n\nTauren arbeiten für gewöhnlich nicht umsonst. Kann also sein, dass dort etwas Arbeit auf Euch wartet.", sourceObjective = "Sucht Barm Steinbrecher in der Eisenhornenklave am Hochberg auf.", progress = "Ihr braucht Hilfe? Dann hoffe ich, dass Ihr im Gegenzug etwas für meine Leute mitgebracht habt, {race}.", completion = "Das ist ein wirklich großzügiges Geschenk, {race}. Das Schmieden kann eine überraschend gefährliche Arbeit sein.\n\nUnd jetzt lasst mich mal diesen Mischbehälter sehen.\n\n\n\nHm, das ist nicht so dramatisch. Ich werde das schnell reparieren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[39431] = { id = 39431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filterinstandsetzung", description = "Deucus den Stoff in diesem Zustand zu bringen, würde ihm nicht viel helfen.\n\nVielleicht gibt es hier in Val'sharah einen Schneider, der ihn für Euch ausbessern kann.\n\nDie Priesterin, die Euch zuvor geholfen hat, kennt womöglich jemanden.", sourceObjective = "Versucht, einen Schneider in Val'sharah zu finden, der Euch die Seidenstreifen wieder zusammennähen kann.", completion = "Ihr wagt es, mir so eine niedere Aufgabe abzuverlangen? Ihr beliebt zu scherzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39432] = { id = 39432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbegreifliche Macht", description = "Der, den sie Gul'dan nennen, hat schon sein eigenes Volk ins Verderben gestürzt und trachtet nun nach dem meinen. Die gefallenen Ausgestoßenen bei Kra'nak haben sich bereits Gul'dan verschworen, nachdem er sie mit Versprechungen über eine Rückkehr in die Lüfte geblendet hat. Den stärksten unter seinen Dienern gewährte er die Macht der Apexis, jedoch verzerrt auf eine Weise, die ich mir nicht erklären kann. Bringt mir eines dieser Fragmente.", sourceObjective = "Erhaltet ein teufelsverderbtes Apexisfragment aus einem Schatz oder von einer der seltenen Kreaturen oder seltenen Elitekreaturen im Tanaandschungel.", progress = "Dies ist nur der Beginn dessen, was Ihr zur Rettung der verbliebenen Arakkoa tun müsst.", completion = "Der Erzmagier berichtete mir, dass die Macht, die diese Kristalle verzerrt hat, von weit jenseits dieser Welt stammt. Ich werde mehr Hilfe benötigen, um herauszufinden, wie ich die Dunkelheit aus meinem Volk verbannen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[39433] = { id = 39433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsichtbare Fänge", description = "Die Verderbnis der Apexis beginnt, in meinem Volk um sich zu greifen. Ihre Energie ist uns so vertraut, dass täglich mehr Arakkoa ihrem Flüstern verfallen. Ihr müsst mir mehr Proben bringen, damit ich mein Volk davor bewahren kann, einem weiteren Fluch zum Opfer zu fallen.", sourceObjective = "Erhaltet 10 teufelsverderbte Apexisfragmente aus einem Schatz, von einer der seltenen Kreaturen oder einer der seltenen Elitekreaturen im Tanaandschungel.", progress = "Ich fürchte, nicht einmal Eure Hilfe vermag das Verderben der Arakkoa abzuwenden.", completion = "Ich werde auch weiterhin Eure Hilfe benötigen, bis wir die Welt von dieser entsetzlichen Präsenz befreit haben, die Gul'dan gerufen hat, uns zu zerstören – welcher Art sie auch immer sein mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[39434] = { id = 39434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[39435] = { id = 39435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oubdob da Smasher" }
quests[39437] = { id = 39437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief in der Höhle", description = "Diese Murlocs werden uns lästig. Sie huschen durch diese Höhlen, als würden sie ihnen gehören. Sie haben sogar ein paar unserer wertvollsten Relikte gestohlen und sie mit ihren fischigen Flossen betatscht.\n\nTötet ein paar, damit ihnen klar wird, dass sie hier nicht das Sagen haben.", sourceObjective = "Tötet 8 Murlocs in der Dunkelsteingrotte.", completion = "Ich konnte die Echos ihrer \"Murlurulurls\" in der Höhle hören. Sie werden es sich nächstes Mal gut überlegen, noch einmal unsere Sachen anzufassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39438] = { id = 39438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guhruhlruhlruh", description = "Üblicherweise sind die Murlocs uns gegenüber eher scheu, aber irgendein größerer von ihnen hat sie in unsere Höhle geführt und jetzt werden sie übermütig.\n\nTötet ihren Anführer. Ich glaube, sein Name lautet \"Guhruhlruhlruh\"... oder so ähnlich.", sourceObjective = "Bezwingt Guhruhlruhlruh.", completion = "Das sollte so einige der Murlocs zum Abhauen bewegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39439] = { id = 39439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelsteinrelikte", description = "Den Murlocs ist es gelungen, einige unserer heiligen Relikte zu stehlen und sie in die tieferen Bereiche der Höhle zu verschleppen.\n\nGlaubt Ihr, dass Ihr sie aufspüren könnt, während wir uns aufwärmen?", sourceObjective = "Bringt die Ketten des Widerstandes, das Rad der Seelenstärke und die Kursrute zurück.", progress = "Wir haben diese Relikte über Generationen hinweg behütet, bevor die Murlocs sie in ihre fischigen Flossen bekommen haben.", completion = "Ihr habt sie gefunden! Auch wenn mir nicht ganz klar ist, wie Ihr sie alle gleichzeitig tragen konntet...", sourceObjectiveStatus = "unverified-source-field" }
quests[39440] = { id = 39440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stemmst du, Brul?", description = "Habt Ihr Muckis? Wenn ja, dann könnt Ihr diese Hanteln zur Statue von Muckibrul und wieder zurück tragen. Wenn Ihr das schafft, reden wir.", sourceObjective = "Tragt die Hanteln zur Statue von Muckibrul und kehrt zu Damrul dem Schtarken zurück.", progress = "Fallen Euch schon die Arme ab?", completion = "Seid stärker als Ihr ausseht, kleines Wesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39441] = { id = 39441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst das Blutende Auge bluten" }
