quests[39444] = { id = 39444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht an der Eisernen Front" }
quests[39445] = { id = 39445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Dämonenschmiede", description = "Die Eiserne Horde schafft ununterbrochen neue Verstärkungen aus ganz Draenor heran, um ihre Position bei der Höllenfeuerzitadelle zu festigen. Wenn es uns nicht gelingt, ihnen den Nachschub abzuschneiden, geraten unsere Pläne in Tanaan in Gefahr.\n\nJetzt ist ein strategischer Angriff auf die Nachschublinien im Eisenfausthafen die erste Wahl, um die Eiserne Horde weiter in die Defensive zu drängen und selbst die Kontrolle zu wahren.", sourceObjective = "Greift die Nachschubeinheiten der Eisernen Horde im Eisenfausthafen im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[39446] = { id = 39446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Dämonenschmiede", description = "Die Eiserne Horde schafft ununterbrochen neue Verstärkungen aus ganz Draenor heran, um ihre Position bei der Höllenfeuerzitadelle zu festigen. Wenn es uns nicht gelingt, ihnen den Nachschub abzuschneiden, geraten unsere Pläne in Tanaan in Gefahr.\n\nJetzt ist ein strategischer Angriff auf die Nachschublinien im Eisenfausthafen die erste Wahl, um die Eiserne Horde weiter in die Defensive zu drängen und selbst die Kontrolle zu wahren.", sourceObjective = "Greift die Nachschubeinheiten der Eisernen Horde im Eisenfausthafen im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[39447] = { id = 39447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf die Ruinen von Kra'nak" }
