quests[39452] = { id = 39452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Eisenfausthafen" }
quests[39453] = { id = 39453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Kil'jaedens Thron", description = "Der Schattenrat hat seine Dämonenmeister auf einem Berg zusammengerufen, den sie \"Kil'jaedens Thron\" nennen. Denkt zurück an den Ersten Krieg: Wir wissen, welche Verheerungen die Legion anrichten kann, wenn sie nicht rechtzeitig aufgehalten wird.\n\nBegebt Euch zu Kil'jaedens Thron und macht dieser Invasion ein Ende, bevor sie überhaupt richtig beginnt.", sourceObjective = "Greift die Truppen des Schattenrats auf Kil'jaedens Thron im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[39454] = { id = 39454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Kil'jaedens Thron", description = "Der Schattenrat hat seine Dämonenmeister auf einem Berg zusammengerufen, den sie \"Kil'jaedens Thron\" nennen. Wir wissen, welche Verheerungen die Legion anrichten kann, wenn sie nicht rechtzeitig aufgehalten wird.\n\nBegebt Euch zu Kil'jaedens Thron und macht dieser Invasion ein Ende, bevor sie überhaupt richtig beginnt.", sourceObjective = "Greift die Truppen des Schattenrats auf Kil'jaedens Thron im Tanaandschungel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[39455] = { id = 39455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höhle der Blutprüfung", description = "Alle Bluttotems und ihre geehrten Gäste müssen eine Prüfung des Blutes bestehen, die in der Höhle unter diesem Außenposten stattfindet.\n\nIch hoffe, dass ihre Einwilligung, Euch daran teilnehmen zu lassen, ein gutes Zeichen ist. Ihr werdet einen Beweis Eurer Taten erbringen, einen Kriegstreiber im Einzelkampf bezwingen und dann ein Opfer an einem Altar tief in der Höhle erbringen müssen.", sourceObjective = "Platziert den Leichnam der Hexe des Waldes auf dem Altar und bezwingt einen Kriegstreiber im Einzelkampf.", progress = "Fürchtet Ihr die Dunkelheit?", completion = "Es heißt, dass ein Fremdling den Hammer von Khaz'goroth schwingen soll. Ich bezweifle, dass Ihr ihn überhaupt heben könntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[39456] = { id = 39456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerwartete Verbündete", description = "Ihr habt mein Vertrauen erlangt. Nicht alle Drogbar sind so gewalttätig wie die Wilden, die Dargrul der Unterkönig anführt, genau wie nicht alle Tauren so blutrünstig sind wie die Bluttotems.\n\nIhr könnt Mayla Hochberg berichten, dass sie unsere volle Unterstützung genießt. Die Höhle, die wir unser Heim nennen, steht Euch ebenfalls offen, {name}.", sourceObjective = "Sprecht mit Mayla Hochberg in Donnertotem.", progress = "Hat Torok sich uns angeschlossen?", completion = "Torok ist tot? Durch... Eure Hand? Er muss wirklich seinem Blutdurst anheimgefallen sein, wenn das geschehen ist.\n\nDass sich die Dunkelsteine jedoch auf unsere Seite geschlagen haben... das ist ein Vorteil, den ich nicht erwartet hatte. Navarrogg war schon immer sehr viel auskömmlicher als Dargrul und seine Brut. Ich danke Euch, dass Ihr dieses einzigartige Bündnis geschlossen habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39460] = { id = 39460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vale POI Event TRACKING" }
