quests[39472] = { id = 39472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz herausschneiden", description = "Diese Karte zeigt die strategischen Standorte der Truppen der Verlassenen in der Gegend um die Graue Wacht. Die östlich ausgerichtete Markierung verweist auf ein Apothekerlager, das die Schreckensreiter mit Nachschub versorgt.\n\nWenn Ihr den für diese Seuche zuständigen Apotheker ausschalten könntet, würdet Ihr die Invasion stoppen und die Schreckensreiter davon abhalten, die Seuche noch weiter zu verbreiten.", sourceObjective = "Tötet Apothekerin Fluchherz beim Schreckensreiterdurchbruch.", completion = "Unglaublich, dass die Verlassenen dreist genug waren, die Seuche genau vor unseren Augen auszubreiten. Ohne ihren Apotheker sind ihre Invasionstruppen jetzt ziemlich zahnlos.\n\nGut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
