quests[39487] = { id = 39487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallzorn", description = "Ein Steinzauberer der Drogbar namens Gelmogg hat unsere heilige Wasserhöhle mit dem Ziel betreten, ihre Kraft in sich aufzunehmen.\n\nWir müssen ihn vernichten, bevor er zu mächtig wird.\n\nEr befindet sich im oberen Abschnitt der Höhle.", sourceObjective = "Tötet Gelmogg.", progress = "Die Drogbar nutzten früher nur Erdmagie, aber jetzt scheinen sie auch Macht aus anderen Quellen zu ziehen.", completion = "Ich habe noch nie gesehen, wie sich ein Drogbar so verwandelt. Der Hammer von Khaz'goroth ist wirklich mächtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[39488] = { id = 39488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gleichgewicht der Elemente", description = "Die Drogbar platzieren ihre scheußlichen Kristalle in unserer Höhle, um die ihr innewohnende Magie zu absorbieren. Wenn sie mit Macht gesättigt sind, sammeln sie sie ein.\n\nWir müssen die Kristalle an uns bringen, sodass die Magie sich wieder verflüchtigen und in das Wasser zurücksickern kann. Sonst werden die Drogbar Wege finden, die Magie für ihre eigenen Zwecke zu manipulieren.", sourceObjective = "Sammelt 10 energieerfüllte Kristalle.", progress = "Ich glaube, jetzt, da die Drogbar in Besitz des Hammers von Khaz'goroth sind, entwickeln sie stärkere Formen der Magie.", completion = "Nun, da die Magie in die Höhle zurückfließt, wird das Gleichgewicht der Elemente wiederhergestellt und die Drogbar werden hier nicht lang verharren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39489] = { id = 39489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfallende Höhlenkletterer", description = "Die Drogbar und ihre brutalen Felsbeißer haben die Höhle überrannt. Sie verderben ihre natürliche Magie und zerstören die Elementare, die seit Ewigkeiten hier wohnen.\n\nLasst uns zusammenarbeiten, um sie aus dieser heiligen Höhle zu vertreiben.", sourceObjective = "Tötet 7 Manadürster der Drogbar oder brutale Felsbeißer.", progress = "Wir müssen die Höhle von den Drogbar befreien.", completion = "Die Höhle ist fast wiederhergestellt...", sourceObjectiveStatus = "unverified-source-field" }
quests[39490] = { id = 39490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befall", description = "Diese Käfer zerstören unsere Ernte und greifen jeden von uns an, der sich ihnen nähert.\n\nWürdet Ihr einige dieser bösartigen Kreaturen vernichten?", sourceObjective = "Tötet 10 verseuchte Maden und 3 übergroße Larven an der Gabe der Erdenmutter.", completion = "Mit weniger von diesen Insekten da draußen kann ich mich wieder um die Ernte kümmern.", sourceObjectiveStatus = "unverified-source-field" }
quests[39491] = { id = 39491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormgul der Befallene", description = "Seit vielen Jahren haben wir in Frieden mit den Drogbar gelebt – unser Stamm mehr als die anderen. Doch bei unserem letzten Handel mit ihnen, an der Flusswindung, wurden wir betrogen.\n\nFür gewöhnlich versorgen sie uns mit kräftigen alchemistischen Mixturen, die verhindern sollen, dass Schädlinge unsere Felder befallen. Aber diesmal haben sie unter der Führung von Ormgul die Pflanzen angegriffen, die uns alle mit Nahrung versorgen.\n\nOrmgul der Befallene ist derjenige, der unsere Felder der Vernichtung preisgegeben hat. Vernichtet ihn und bringt mir, was auch immer er benutzt hat, um die Käfer auf unser Land zu locken.", sourceObjective = "Tötet Ormgul den Befallenen und nehmt sein Käferspray.", progress = "Die Flussmähnen sind ein friedvoller Stamm. Als Gegenleistung für Schutz und Ausrüstung versorgen wir die anderen mit Nahrung und Heilung.\n\nWenn ich jedoch dazu gezwungen werde, bin ich gewillt, meine Magie zu gewaltsameren Zwecken einzusetzen.", completion = "Jetzt haben wir das, womit sie unsere Felder besprüht haben. Ich frage mich, wozu wir es einsetzen könnten...", sourceObjectiveStatus = "unverified-source-field" }
quests[39494] = { id = 39494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 008 - Pinerock Basin" }
quests[39495] = { id = 39495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Versteckspiel mehr", description = "Jetzt, wo Ihr die Dämonen enttarnt habt, kann ich sie auch spüren. Ich spüre sogar einen extrem mächtigen Teufelslord tief in der Höhle. Entreißt ihm seine Macht, solange Ihr noch könnt.\n\nWenn Ihr den Anführer ausschaltet, kümmern wir uns um den Rest seiner Truppen in der Höhle.", sourceObjective = "Tötet Teufelslord Caza und beansprucht seine Teufelskraft.", completion = "Ausgezeichnet. Ihr habt die Macht dieses Teufelslords absorbiert und seid noch stärker geworden.\n\nJetzt können wir uns ganz auf die Vernichtung der Brutkönigin und ihrer Legionskräfte konzentrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39496] = { id = 39496, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Strom des Flusses", description = "Jetzt, da die größte Gefahr gebannt ist, können wir Bäuerin Maya die Aufsicht über die Felder überlassen.\n\nDas bedeutet allerdings nicht, dass wir bereits das Schlimmste hinter uns gebracht haben, {name}. Die Fischerei ist genauso wichtig wie unsere Felder, und sie ist sogar in noch größerer Gefahr, sollten Angler Fischkorbs Worte der Wahrheit entsprechen.", sourceObjective = "Trefft Euch mit Angler Fischkorb an den Weißwasserschnellen.", completion = "Ich bin froh, dass Ihr gerade jetzt kommt. Die Drogbar sind dabei, ihre Angriffe zu verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[39497] = { id = 39497, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Waygate" }
quests[39498] = { id = 39498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochwasser", description = "Die Flusswindung! Ist es das, wovon der Unterkönig sprach?\n\nDas ist meine Heimat und der Ort, wo wir unsere Wintervorräte lagern. Wir müssen so schnell wie möglich dorthin und sie warnen.\n\nTrefft mich dort.", sourceObjective = "Sprecht mit Jale Flussmähne an der Flusswindung.", completion = "Wir scheinen den Unterkönig hier besiegt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[39499] = { id = 39499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brunnen der Seelen", description = "Je mehr Diener Gul'dans Ihr besiegt, desto schwächer wird seine Kontrolle über diese dämonische Zitadelle und so kann ich Euch und Eure Verbündeten tiefer in diese dunklen Hallen teleportieren. Wenn ich nur ein paar Seelenrückstände hätte – vier, zum Beispiel – wäre das alles nicht nötig und ich könnte Euch einfach mit ihrer Macht direkt in die oberen Bereiche der Zitadelle schicken.", sourceObjective = "Sammelt 4 Seelenrückstände von Blutschatten in der normalen Version der Höllenfeuerzitadelle.", progress = "Konntet Ihr ein paar von diesen Seelenrückständen finden, von denen ich gesprochen habe?", completion = "A-ha! Seelenrückstände!\n\n<Khadgar nimmt die Fragmente entgegen und konzentriert sich fest auf sie.>\n\nWunderbar! Damit könnt Ihr und Eure Verbündeten direkt in die oberen Bereiche der Zitadelle gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39500] = { id = 39500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brunnen der Seelen", description = "Je mehr Diener Gul'dans Ihr besiegt, desto schwächer wird seine Kontrolle über diese dämonische Zitadelle und so kann ich Euch und Eure Verbündeten tiefer in diese dunklen Hallen teleportieren. Wenn ich nur ein paar Seelenrückstände hätte – vier, zum Beispiel – wäre das alles nicht nötig und ich könnte Euch einfach mit ihrer Macht direkt in die oberen Bereiche der Zitadelle schicken.", sourceObjective = "Sammelt 4 Seelenrückstände von Blutschatten in der heroischen Version der Höllenfeuerzitadelle.", progress = "Konntet Ihr ein paar von diesen Seelenrückständen finden, von denen ich gesprochen habe?", completion = "A-ha! Seelenrückstände!\n\n<Khadgar nimmt die Fragmente entgegen und konzentriert sich fest auf sie.>\n\nWunderbar! Damit könnt Ihr und Eure Verbündeten direkt in die oberen Bereiche der Zitadelle gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39501] = { id = 39501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brunnen der Seelen", description = "Je mehr Diener Gul'dans Ihr besiegt, desto schwächer wird seine Kontrolle über diese dämonische Zitadelle und so kann ich Euch und Eure Verbündeten tiefer in diese dunklen Hallen teleportieren. Wenn ich nur ein paar Seelenrückstände hätte – vier, zum Beispiel – wäre das alles nicht nötig und ich könnte Euch einfach mit ihrer Macht direkt in die oberen Bereiche der Zitadelle schicken.", sourceObjective = "Sammelt 4 Seelenrückstände von Blutschatten in der mythischen Version der Höllenfeuerzitadelle.", progress = "Konntet Ihr ein paar von diesen Seelenrückständen finden, von denen ich gesprochen habe?", completion = "A-ha! Seelenrückstände!\n\n<Khadgar nimmt die Fragmente entgegen und konzentriert sich fest auf sie.>\n\nWunderbar! Damit könnt Ihr und Eure Verbündeten direkt in die oberen Bereiche der Zitadelle gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39502] = { id = 39502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teufelsspitze", description = "Das alles wäre so viel einfacher, wenn wir nur direkt zur Spitze der Zitadelle teleportieren könnten, wo Gul'dan seine finstere Magie wirkt, nicht wahr? Aber während die Zitadelle von Dämonenmagie durchdrungen ist, reicht meine Macht nicht bis dort hinauf.\n\nWenn ich mächtige Teufelsessenzen zur Verfügung hätte, könnte ich meine Magie daran anpassen und ihre Verteidigung unterwandern. Doch die einzige Quelle für solche Energien ist an der Spitze der Zitadelle selbst zu finden. Was für eine Zwickmühle...", sourceObjective = "Sammelt 4 Teufelsessenzen von Mannoroth in der normalen Version der Höllenfeuerzitadelle.", progress = "Wart Ihr schon an der Spitze der Zitadelle, damit ich Euch dorthin zurückschicken kann?", completion = "Ihr habt es vollbracht!\n\nMerkwürdig, diese Teufelsessenzen stammen eindeutig von dem Grubenlord Mannoroth... Wir um alles in der Welt ist es Euch gelungen... es ist, als hättet Ihr das schon einmal gemacht!\n\n<Khadgar sieht Euch eindringlich an.>\n\nWie dem auch sei! Mit dieser Macht kann ich Euch und Eure Mitstreiter direkt zur Spitze der Zitadelle schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[39503] = { id = 39503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 011 - Pinerock Basin" }
quests[39504] = { id = 39504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teufelsspitze", description = "Das alles wäre so viel einfacher, wenn wir nur direkt zur Spitze der Zitadelle teleportieren könnten, wo Gul'dan seine finstere Magie wirkt, nicht wahr? Aber während die Zitadelle von Dämonenmagie durchdrungen ist, reicht meine Macht nicht bis dort hinauf.\n\nWenn ich mächtige Teufelsessenzen zur Verfügung hätte, könnte ich meine Magie daran anpassen und ihre Verteidigung unterwandern. Doch die einzige Quelle für solche Energien ist an der Spitze der Zitadelle selbst zu finden. Was für eine Zwickmühle...", sourceObjective = "Sammelt 4 Teufelsessenzen von Mannoroth in der heroischen Version der Höllenfeuerzitadelle.", progress = "Wart Ihr schon an der Spitze der Zitadelle, damit ich Euch dorthin zurückschicken kann?", completion = "Ihr habt es vollbracht!\n\nMerkwürdig, diese Teufelsessenzen stammen eindeutig von dem Grubenlord Mannoroth... Wie um alles in der Welt ist es Euch gelungen... es ist, als hättet Ihr das schon einmal gemacht!\n\n<Khadgar sieht Euch eindringlich an.>\n\nWie dem auch sei! Mit dieser Macht kann ich Euch und Eure Mitstreiter direkt zur Spitze der Zitadelle schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[39505] = { id = 39505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Teufelsspitze", description = "Das alles wäre so viel einfacher, wenn wir nur direkt zur Spitze der Zitadelle teleportieren könnten, wo Gul'dan seine finstere Magie wirkt, nicht wahr? Aber während die Zitadelle von Dämonenmagie durchdrungen ist, reicht meine Macht nicht bis dort hinauf.\n\nWenn ich mächtige Teufelsessenzen zur Verfügung hätte, könnte ich meine Magie daran anpassen und ihre Verteidigung unterwandern. Doch die einzige Quelle für solche Energien ist an der Spitze der Zitadelle selbst zu finden. Was für eine Zwickmühle...", sourceObjective = "Sammelt 4 Teufelsessenzen von Mannoroth in der mythischen Version der Höllenfeuerzitadelle.", progress = "Wart Ihr schon an der Spitze der Zitadelle, damit ich Euch dorthin zurückschicken kann?", completion = "Ihr habt es vollbracht!\n\nMerkwürdig, diese Teufelsessenzen stammen eindeutig von dem Grubenlord Mannoroth... Wie um alles in der Welt ist es Euch gelungen... es ist, als hättet Ihr das schon einmal gemacht!\n\n<Khadgar sieht Euch eindringlich an.>\n\nWie dem auch sei! Mit dieser Macht kann ich Euch und Eure Mitstreiter direkt zur Spitze der Zitadelle schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[39507] = { id = 39507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 062 - Pinerock Basin" }
quests[39509] = { id = 39509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die blutbefleckten Klingen Zeth'Gols", description = "Die Orcs des Blutenden Auges praktizieren Blutmagie – das is' so was wie Voodoo, nur tut's mehr weh. Sie schneid'n sich ins eigene Fleisch. Viele von ihnen lauf'n dazu mit geschwungenen Ritualklingen rum.\n\nBringt mir ihre Klingen, Kommandant. Wir können ihre eigenen Waffen gegen sie einsetz'n.", sourceObjective = "Erbeutet 25 Ritualklingen des Blutenden Auges von Orcs des Blutenden Auges in Zeth'Gol.", progress = "Im Gebiet des Blutenden Auges müsst Ihr gut aufpass'n. Hier kämpfen sie nicht fair.\n\nWir natürlich auch nicht.", completion = "<Denjai prüft eine Klinge mit seinem Daumen. Ein unheimliches Lächeln überzieht sein Gesicht.>\n\nDie werden den Zweck erfüllen, Kommandant. Sehr gut sogar.", sourceObjectiveStatus = "unverified-source-field" }
quests[39510] = { id = 39510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Drecksarbeit", description = "Die restlichen Trupp'n der Eisernen Horde nähern sich Tanaan über den Eisenfausthafen. Wenn wir wüsst'n, wer da kommt und geht, könnten wir mit unsrer Werft ein wenig Chaos anricht'n.\n\nGeht zum Eisenfausthafen und schnüffelt dort ein wenig rum!", sourceObjective = "Sammelt 15 Marinebefehle der Eisernen Horde von Truppen im Eisenfausthafen.", progress = "So, habt Ihr was aufgeschnappt, Kommandant?", completion = "Das ist das gute Zeug, Kommandant.\n\nIch schick' sofort einen Boten damit zu Eurer Werft. Macht Euch keine Sorgen um ihn – meine Jäger flitz'n durch den Dschungel, wie wenn sie unsichtbar wär'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[39511] = { id = 39511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blut gefallener Brüder", description = "Orcs, die Gul'dans Gift trink'n, verwandeln sich in Teufelsbestien, seelenlose Wilde.\n\nLady Liadrin und die Blutritter glaub'n, dass sie die Orcs vielleicht zurückverwandeln können. Sie woll'n Blutproben von Orcs, die sich gerade erst verwandelt hab'n. Besorgt ihnen das Blut, {name}!\n\nTeufelsorcs könnt Ihr in ganz Tanaan find'n, aber an der Eisernen Front, bei der Dämonenschmiede und bei Kil'jaedens Thron gibt es davon massenweise.", sourceObjective = "Sammelt 20 Phiolen mit Teufelsblut von Teufelsorcs im Tanaandschungel.", progress = "Habt Ihr sie ausblut'n lass'n, Kommandant?", completion = "Dann lass' ich die zu Lady Liadrin bring'n.\n\nGlaubt Ihr wirklich, für diese Monster kann's einen Weg zurück geben, Kommandant? Ihr seid zuversichtlicher als ich, Mann.", sourceObjectiveStatus = "unverified-source-field" }
quests[39512] = { id = 39512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Schattenrats", description = "Gul'dan vergrößert seinen Schattenrat wie 'ne Spinne ihr Netz, Mann. Aber ein paar von den Neulingen sind nich' clever. Schreib'n Geheimnisse auf und vergess'n, sie zu verbrennen.\n\nGreift Euch die Hohlköpfe, wenn sie draußen unterwegs sind, und besorgt mir ihre Geheimnisse! Sie lungern bei den Arakkoa in den Ruinen von Kra'nak oder bei Kil'jaedens Thron rum.", progress = "Was gefunden, Kommandant?", completion = "Genau danach haben wir gesucht, Mann! Meine Leute mach'n sich da sofort ran, Kommandant." }
quests[39513] = { id = 39513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sha'naarazzia", description = "Die Draenei beim Tempel von Sha'naar haben in den Bergen nach gut'n Kristallen für ihren Voodoo gebuddelt, aber jetz mach'n das die Dämonen. Wir müss'n denen die Kristalle abknöpf'n, Kommandant. Greift die Minen hinter dem Tempel an und schnappt Euch so viele, wie Ihr tragen könnt.", progress = "Da oben was gefunden, Kommander?", completion = "Hm, seh'n gar nich' gefährlich aus, was?\n\nIch bring die in Sicherheit, Kommandant. Vielleicht wiss'n die Blutelfen was damit anzufangen." }
quests[39514] = { id = 39514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seh'n wir mal unter die Haube", description = "Der alte Grommash Höllschrei hat's geschafft, die Gronn als Kriegswaffe zu benutz'n. Vol'jin will wiss'n, wie er das angestellt hat.\n\nGeht zur Eisernen Front, pustet einem von den Riesenviechern die Lichter aus un' bringt mir seinen Harnisch. Allein braucht Ihr aber mächtig viel Mojo, um das zu schaffen.", sourceObjective = "Erbeutet einen Kriegsgronnharnisch von einem Eisernen Kriegsgronn an der Eisernen Front im Tanaandschungel.", progress = "Habt Ihr einen um die Ecke gebracht, Mann?", completion = "Ihr habt das Ding bis hierher geschleift, Mann? Respekt, vielleicht habt Ihr selber 'n bisschen Gronn im Blut, Kommandant!\n\n Das da schick'n wir den Goblins in Orgrimmar. Denen fall'n bestimmt die Augen aus'm Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[39515] = { id = 39515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spürt meine brennende Rachsucht!", description = "Darum fürchtet uns die Legion. Nur wir können ihre Geheimnisse gegen sie verwenden und dabei noch stärker werden, als sie es jemals sein könnten.\n\nSchnell, {name}, lehrt uns, was ihr gelernt habt.", sourceObjective = "Lehrt Eure versammelten Dämonenjäger die Kunst der Rachsucht.", completion = "Ich gebe mir selbst die Schuld, {name}. Mannethrel war zu geschwächt. In uns tobt eine nie endende Schlacht um die Kontrolle der Dämonenkraft, die wir alle in uns aufgenommen haben.\n\nVielleicht wäre es das Beste, die Unterweisungen für den Moment zu verschieben. Wir können uns keine weiteren Verluste erlauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[39516] = { id = 39516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lehrt die Illidari, was Verwüstung bedeutet!", description = "Darum fürchtet uns die Legion. Nur wir können ihre Geheimnisse gegen sie verwenden und dabei noch stärker werden, als sie es jemals sein könnten.", sourceObjective = "Lehrt Eure Dämonenjäger die Wege der Verwüstung.", progress = "Wir erwarten Eure Anweisungen, {name}.", completion = "Ich gebe mir selbst die Schuld, {name}. Mannethrel war zu geschwächt. In uns tobt eine nie endende Schlacht um die Kontrolle der Dämonenkraft, die wir alle in uns aufgenommen haben.\n\nVielleicht wäre es das Beste, die Unterweisungen für den Moment zu verschieben. Wir können uns keine weiteren Verluste erlauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[39517] = { id = 39517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Secrets - Havoc Spec Tracking Event" }
quests[39518] = { id = 39518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Secrets - Vengeance Spec Tracking Event" }
quests[39519] = { id = 39519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonentöter von Tanaan", description = "Schaut nach Norden, {class}. Der Himmel nimmt eine widerliche grüne Farbe an. Gul'dans Beschwörungsportale haben noch nicht ihre volle Kraft erreicht, und doch liegt bereits der Gestank von Dämonen in der Luft.\n\nTötet sie, {name}. Vernichtet so viele von ihnen, wie Ihr nur könnt, bevor sie einen Weg nach Azeroth finden. Der Tempel von Sha'naar ist überrannt, ebenso Kil'jaedens Thron – allerdings begegnet Ihr ihnen sicher auch an anderen Stellen im Dschungel.", sourceObjective = "Tötet 20 Dämonen im Tanaandschungel.", completion = "Wie fühlt sich das an, {name}? Der Legion direkt ins Auge zu blicken und zu sagen... \"Nicht mit mir.\"?", sourceObjectiveStatus = "unverified-source-field" }
quests[39520] = { id = 39520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Dominance" }
quests[39521] = { id = 39521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Vorherrschaft", description = "Die Allianz weigert sich, in Ashran nachzugeben. Zeigt ihr, dass die Horde nicht einfach tatenlos zusieht, während sie die Macht des alten Ogerreichs für ihre Zwecke an sich reißt.", sourceObjective = "Besiegt die Allianz an den Ereignisstandorten in Ashran und besiegt Großmarschall Tremblade.", sourceObjectiveStatus = "unverified-source-field" }
quests[39522] = { id = 39522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorherrschaft in Ashran", description = "Wie wir schon befürchtet haben, versucht die Horde, mit Raubzügen ihre Stellung hier auf der Insel zu festigen. Zieht hinaus und zeigt ihnen, dass die Allianz sich derartige Überfälle nicht gefallen lässt.", sourceObjective = "Besiegt die Horde an den Ereignisstandorten in Ashran und besiegt den Obersten Kriegsfürsten Volrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[39523] = { id = 39523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Vorherrschaft", description = "Wie wir schon befürchtet haben, versucht die Horde, mit Raubzügen ihre Stellung hier auf der Insel zu festigen. Zieht hinaus und zeigt ihnen, dass die Allianz sich derartige Überfälle nicht gefallen lässt.", sourceObjective = "Besiegt die Horde an allen Ereignisstandorten in Ashran und liquidiert den Obersten Kriegsfürsten Volrath.", sourceObjectiveStatus = "unverified-source-field" }
quests[39524] = { id = 39524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Findet sie, jagt sie, tötet sie. Erteilt unseren Feinden eine Lektion, die sie niemals vergessen werden.", sourceObjective = "Tötet 200 gegnerische Spielercharaktere.", sourceObjectiveStatus = "unverified-source-field" }
quests[39525] = { id = 39525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet sie alle!", description = "Die Übergriffe der Horde dürfen wir nicht erlauben. Bekämpft sie, bis niemand verbleibt!", sourceObjective = "Tötet 200 gegnerische Spielercharaktere.", sourceObjectiveStatus = "unverified-source-field" }
quests[39526] = { id = 39526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht nachlassen", description = "Wir haben die Oberhand über Gul'dans Diener, Kommandant! Wenn Euch danach is', sollten wir auch ihre anderen Stützpunkte unter Druck setzen.", sourceObjective = "Schließt 2 Bonuszielgebiete im Tanaandschungel ab.", completion = "Ihr habt's geschafft, Kommandant! Jeden Tag erobern wir ein Stück mehr von diesem Dschungel.", sourceObjectiveStatus = "unverified-source-field" }
quests[39527] = { id = 39527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungsquest: Azsharas Zorn" }
quests[39528] = { id = 39528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heroische Belohnungsquest: Azsharas Zorn" }
quests[39529] = { id = 39529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Klauen und Zähnen", description = "Hinter dem kläglichen Schutz, den diese Festungsmauern bieten, lauert der Dschungel. Spürt Ihr es? Die ungezähmte Wildnis, {class}. Sie weckt unsere tierischen Instinkte. Man fühlt sich nie so lebendig, wie wenn man mit dem Tod ringt.\n\nSchließt Euch meiner Jagd an, {name}! Sammelt Zähne von den Wildtieren. Die Verheerer im Dornsumpf, die Raptoren in der Zorammarsch – selbst die Meerestiere am Strand und die kleinen Schotlingpflanzen: sie alle haben Zähne. Bringt sie mir!", sourceObjective = "Sammelt 100 Tanaandschungelzähne von den verschiedenen Wildtieren des Tanaandschungels.", progress = "Ich nehme an, Eure Jagd verläuft gut?", completion = "Oh, eine ganz schöne Sammlung. Wie viele davon musstet Ihr Euch aus dem Fleisch ziehen? Aufregend, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[39530] = { id = 39530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Akt des Schmiedens", description = "Eure neue Waffe ist sehr mächtig, aber meine Schmiede beherrschen ihr Handwerk schon seit Tausenden von Jahren. Sprecht mit Meisterschmied Helgar und findet heraus, was für Verbesserungen er vornehmen kann.", sourceObjective = "Sprecht mit Meisterschmied Helgar in der Schmiede in den Hallen der Tapferkeit.", completion = "Das ist ein erstaunliches Artefakt... Ich sehe direkt, dass sich in ihm großes Potenzial verbirgt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39531] = { id = 39531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 00x - Steamy Romance Novel" }
quests[39532] = { id = 39532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwingt sie in die Knie", description = "Seit dem Fall der Schwarzfelsgießerei ist Gul'dan damit beschäftigt, die Eiserne Horde in etwas... Schlimmeres zu verwandeln. Die Orcs, die sich bisher entweder aus Furcht oder Rachsucht um Grommash geschart hatten, geben sich jetzt der Dämonenmagie hin.\n\nTretet ihnen auf dem Schlachtfeld von Tanaan entgegen und dezimiert Gul'dans Truppen. Ob Orc oder Teufelsorc ist einerlei. Gebt der Eisernen Horde den Gnadenstoß!", sourceObjective = "Tötet 25 Orcs der Eisernen Horde im Tanaandschungel.", completion = "Ihr habt Ihnen den ehrenvollen Tod gewährt, den sie sich so gewünscht haben, {name}. Bald wird Gul'dan niemand mehr bleiben, der seine Drecksarbeit macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39533] = { id = 39533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nogginclobber Arena" }
