quests[39564] = { id = 39564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Murktide Alpha" }
quests[39565] = { id = 39565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Dschungel ist die Hölle los", description = "Diesen Katzenmenschen muss mal jemand zeigen, wer hier die Hosen anhat. Murkst all ihre Champions ab und alles, was im Dschungel kreucht und fleucht, wird Euch Respekt zollen.\n\nIhr werdet die Totems hier brauchen, um sie hervorzulocken.", sourceObjective = "Besiegt die drei Arenachampions von Fangri'la.", completion = "Gut gemacht, Mann. Wir dürf'n ihnen keine Schwäche zeig'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[39566] = { id = 39566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Wissen", description = "Habt Ihr irgendwelche verlorenen Relikte in Azsuna gesehen, während Ihr so herumscharwenzelt seid? Laut meiner Quellen gibt es dort wahre Schätze. Und diesen Gerüchten sollten wir nachgehen!", sourceObjective = "Sucht nach uralten Relikten an der Küste von Azsuna.", completion = "Ein nasser, alter Foliant liegt halb vergraben im Schlamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[39567] = { id = 39567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die blutbefleckten Klingen Zeth'Gols", description = "Der Klan des Blutenden Auges ist berüchtigt für seine Blutriten. Diese Wilden ritzen sich Symbole in die Haut und stellen Tränke aus dem Blut ihrer stärksten Krieger her.\n\nDie geschwungenen zeremoniellen Klingen, die sie verwenden, besitzen eine ganz eigene Macht. Bringt mir ein paar davon. Wir werden ihnen Ihre grausamen Werkzeuge entreißen und dabei noch etwas über unsere Feinde lernen.", sourceObjective = "Erbeutet 25 Ritualklingen des Blutenden Auges von Orcs des Blutenden Auges in Zeth'Gol.", progress = "Wir Draenei hatten vor diesem Konflikt nur wenig Kontakt mit dem Blutenden Auge. Sie waren ein zurückgezogener Klan, der einen der lebensfeindlichsten Landstriche Draenors sein Zuhause nannte.", completion = "Was für schreckliche Instrumente! Wir werden sie gründlich untersuchen und sie dann zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[39568] = { id = 39568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Drecksarbeit", description = "Die zerschlagenen Überreste der Eisernen Horde strömen über den Eisenfausthafen in den Tanaandschungel. Wenn wir mehr über ihre Flotte wüssten, können wir Gegenmaßnahmen aus unserer Werft im Schattenmondtal entsenden.\n\nVielleicht könntet Ihr etwas Marineaufklärungsarbeit für uns leisten?", sourceObjective = "Sammelt 15 Marinebefehle der Eisernen Horde von Truppen im Eisenfausthafen.", progress = "Der Prophet sagt, es ist immer weise, seinen Feind zu kennen, bevor man ihm entgegentritt.", completion = "Wunderbar, wunderbar. Ich schicke einen Boten mit diesen Informationen zu Eurer Werft. Habt Dank, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[39569] = { id = 39569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprengt ihre teuflischen Ketten", description = "Gul'dans teuflisches Gift verwandelt ohnehin schon wilde Orcs in hasserfüllte, seelenlose Kreaturen. Doch wäre er noch bei uns, würde Prophet Velen nicht das gesamte Volk aufgeben. Wenn Ihr Proben ihres Blutes in unseren Besitz bringen könntet, gelingt es uns vielleicht, den Prozess umzukehren.\n\nIhr findet Höllenorcs überall in Tanaan, doch am dichtesten sind sie an der Eisernen Front, der Dämonenschmiede und auf Kiljaedens Thron konzentriert.", sourceObjective = "Sammelt 20 Phiolen mit Teufelsblut von Teufelsorcs im Tanaandschungel.", progress = "Konntet Ihr ein paar Blutproben sammeln? Ich frage Euch wohl besser nicht, wie Ihr an sie gelangt seid, Kommandant.", completion = "Danke, Kommandant. Unsere Gelehrten werden diese Proben umgehend untersuchen!\n\nWir dürfen die Hoffnung nicht aufgeben. Unsere Geschwister, die Eredar, sind scheinbar unwiederbringlich verloren, doch auf Azeroth haben es Orcs geschafft, sich von der Brennenden Legion zu befreien...", sourceObjectiveStatus = "unverified-source-field" }
quests[39570] = { id = 39570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Schattenrats", description = "Gul'dan hat sich ein Spionagenetzwerk eingerichtet – den sogenannten \"Schattenrat\". Bei seinen verzweifelten Bemühungen, die Kontrolle über den Tanaandschungel zu behalten, ist der Schattenrat unvorsichtig geworden. Seine Mitglieder agieren in aller Öffentlichkeit und rekrutieren Arakkoa in den Ruinen von Kra'nak oder beschwören Dämonen an Kil'jaedens Thron.\n\nMacht Mitglieder des Schattenrats ausfindig und sichert jegliche Informationen, die sie zu leichtfertig waren, zu zerstören!", progress = "Was habt Ihr erfahren?", completion = "Ja... Ja! So viele Unterlagen. Ah, manche davon sind chiffriert. Allerdings nicht sehr raffiniert. Unsere Gelehrten werden hieraus viel in Erfahrung bringen können. Gute Arbeit, Kommandant!" }
quests[39571] = { id = 39571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sha'naarazzia", description = "Die Draenei im Tempel von Sha'naar schürften in den Bergen nach perfekten Kristallen, um unsere arkanen Geräte zu betreiben. Leider ist der Tempel mittlerweile verloren – wir wurden von den Sargerei unterwandert.\n\n{name}, es ist unabdingbar, dass Ihr in diese Minenschächte hinabsteigt und die Kristalle für uns sicherstellt, bevor die Sargerei sie für ihre Dämonenrituale missbrauchen können. Wenn Ihr dabei nicht umhin kommt, unsere ehemaligen Brüder und Schwestern zu töten... so sei es.", progress = "Dieser Tempel war einmal ein Ort des Friedens und der Einkehr. Ich fürchte er ist nicht zu retten.", completion = "Sehr gut, {name}. Unsere Gelehrten werden wissen, wie sie diese Kristalle einzusetzen haben, um unser Volk zu beschützen und ihm Kraft zu verleihen." }
quests[39572] = { id = 39572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moozys Abenteuer", description = "<Moozy treibt den Fluss hinab und muss wieder zu seiner Mutter gebracht werden.>", sourceObjective = "Bringt Moozy zu Sella Wasserweise an den Weißwasserschnellen.", completion = "Moozy! Ich danke den Geistern, dass es dir gut geht! Oh, ich danke Euch, dass Ihr ihn zurückgebracht habt. Habt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[39573] = { id = 39573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seh'n wir mal unter die Haube", description = "Wir haben immer geglaubt, dass die urzeitlichen Kreaturen von Draenor nicht gezähmt werden könnten. Und doch hat die Eiserne Horde einen Weg gefunden, die Gronn als Waffen einzusetzen. Es wäre für uns von Vorteil, wenn wir herausfinden könnten, wie.\n\nReist zur Eisernen Front, tötet einen Kriegsgronn und nehmt sein Geschirr. Vielleicht möchtet Ihr Euch dafür Hilfe holen.", sourceObjective = "Erbeutet einen Kriegsgronnharnisch von einem Eisernen Kriegsgronn an der Eisernen Front im Tanaandschungel.", progress = "Exarch Maladaar berichtet von Chaos auf dem Schlachtfeld. Konntet Ihr durchhalten?", completion = "Meine Güte, ist das gewaltig. Danke, dass Ihr es den ganzen Weg hierhergetragen habt.\n\nEs gibt immer noch so viel auf dieser Welt, was mein Volk lernen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[39574] = { id = 39574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht nachlassen", description = "Gul'dans Diener sind auf der Flucht, Kommandant! Wenn Ihr über die Stärke verfügt, wäre jetzt die Gelegenheit, weiter vorzustoßen und ein paar seiner anderen Festungen zu überfallen.", sourceObjective = "Schließt 2 Bonuszielgebiete im Tanaandschungel ab.", completion = "Das sind wunderbare Neuigkeiten, Kommandant. Bald werden wir Gul'dans grauenhafte Zitadelle vollständig umzingelt haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[39575] = { id = 39575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad des Huln", description = "Armeen sind für erfolgreiche Schlachten unerlässlich. Symbole jedoch ebenfalls.\n\nFür unser Volk gibt es nur wenige Symbole, die mehr Wert für uns besitzen als der Segen unserer ältesten Vorfahren.\n\nMayla muss auf dem Pfad des Huln wandeln.\n\nDer Pfad ist gefährlich und sie darf nur zwei Begleiter mit sich nehmen: einen Geistwandler, der ihr den Weg weist, und einen Champion, der sie beschützt.\n\nWerdet Ihr als Champion teilnehmen?", sourceObjective = "Folgt Geistwandler Ebenhorn auf dem Pfad des Huln.", completion = "Es geht ganz schön tief hinunter. Seid vorsichtig hier drin, dies ist kein sicherer Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[39576] = { id = 39576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echos von Todesschwinge" }
quests[39577] = { id = 39577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uraltes Geheimnis", description = "Bevor Mayla zum Oberhäuptling erklärt werden kann, muss sie noch eine weitere Vision erhalten. Ich möchte sie auch Euch zeigen.\n\nEs handelt sich um ein uraltes Geheimnis, das nur innerhalb der Blutlinie von Hochberg weitergegeben wurde. Ich bitte Euch, dass Ihr es ebenfalls wahrt.", sourceObjective = "Unterstützt Geistwandler Ebenhorn in Neltharions Hort.", completion = "An jenem Tag befreite der Hammer mich von der Verderbnis des schwarzen Drachenschwarms.\n\nAus Dankbarkeit diene ich der Familie Hochberg, seit Huln mich aus diesem Loch befreite.\n\nEs war mir eine Ehre und brachte mir Freude, zu erleben, wie all seine Nachfahren den Titel des Oberhäuptlings erhielten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39578] = { id = 39578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Titanisches Kräftemessen", description = "Die Geschichte von Huln endete nicht damit, dass er den Hammer von Khaz'goroth in seinen Besitz brachte.\n\nNein. Für diesen Teil müssen wir tiefer in die Höhle eindringen. Dort wartet eine letzte Kohlenpfanne auf uns.\n\nKommt, lasst uns sehen, was als Nächstes geschehen ist.", sourceObjective = "Findet den Geist von Huln Hochberg und helft ihm.", completion = "Und damit verbannte Huln Todesschwinge nach Tiefenheim und beanspruchte den Hammer von Khaz'goroth als seinen Preis.\n\nDoch um eine letzte Angelegenheit musste er sich noch kümmern...", sourceObjectiveStatus = "unverified-source-field" }
quests[39579] = { id = 39579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hintertür", description = "Es wird etwas dauern, bis Mayla das verarbeitet hat.\n\nWir aber sollten jetzt nach Donnertotem zurückkehren.\n\nGleich südlich von hier gibt es einen Tunnel, der uns durch die alte Sklavenenklave der Drogbar bis zu einer Lichtung dahinter führen wird.\n\nWir unterhalten dort einen kleinen Himmelshornwachposten, um sicherzustellen, dass niemand das Gewölbe ohne unser Wissen betritt oder verlässt. Es sollte ihnen möglich sein, uns zurückzufliegen.", sourceObjective = "Flieht aus dem Hort.", completion = "Ich fand es immer seltsam, dass der alte Ebenhorn niemals zu altern schien. Oder zumindest sah er immer alt aus, wurde aber nie älter.", sourceObjectiveStatus = "unverified-source-field" }
quests[39580] = { id = 39580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Oberhäuptling", description = "Jetzt verstehe ich, was Ebenhorn mir schon seit einer Weile zu verstehen geben will.\n\nUnsere Leute brauchen keinen Hammer, sondern einen Anführer, der jeder Bedrohung entgegentritt, selbst wenn wir anderen uns fürchten.\n\nUnd... das bleibt zwischen uns... ich habe natürlich Angst, aber ich bin auch entschlossen.\n\nKehren wir zurück nach Donnertotem, um uns auf den Krieg vorzubereiten.", sourceObjective = "Sprecht mit Mayla Hochberg in Donnertotem.", completion = "Selbst ohne den Hammer weiß ich, was als Nächstes zu tun ist. Wenn unsere Truppen sich gesammelt haben, werden wir den Unterkönig angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39581] = { id = 39581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonentöter von Tanaan", description = "Dämonen! Ich hasse sie!\n\nGul'dan errichtet mit jeder weiteren Stunde immer mehr Beschwörungsportale. Es gibt nur einen Weg, die Flut aufzuhalten, {name}.\n\n<Parvink schlägt sich mit der gepanzerten Faust in die offene Hand.>\n\nSie zu zerschmettern!\n\nDer Tempel von Sha'naar wäre ein guter Anfang. Oder geht zu Kil'jaedens Thron, wenn Ihr nach einer echten Herausforderung sucht.", sourceObjective = "Tötet 20 Dämonen im Tanaandschungel.", completion = "Sehr gut! Ihr habt es schon drauf, {name}. Schlagt ein!", sourceObjectiveStatus = "unverified-source-field" }
quests[39582] = { id = 39582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Klauen und Zähnen", description = "Diese Feiglinge, die das Holz im Dschungel umherschleppen, reden immer davon, wie gefährlich es ist. Wisst Ihr, zwischen der Verheererhöhle im Süden und den Raptoren, die in der Zorammarsch herumlaufen, haben sogar die Kreaturen am Strand und die Schotlinge Zähne!\n\nWas meint Ihr? Gehen wir beide ein wenig auf die Jagd? Sammelt Zähne von Wildtieren. Je größer das Tier, desto mehr Zähne. Wir treffen uns wieder hier und vergleichen dann unseren Fang!", sourceObjective = "Sammelt 100 Tanaandschungelzähne von den verschiedenen Wildtieren des Tanaandschungels.", progress = "Bereit, die Notizen zu vergleichen?", completion = "<Parvink ist über und über von blutigen Kratzern und zerfetzten Blättern bedeckt.>\n\nHe, nicht schlecht! Sagen wir mal, unentschieden. Dieser Dschungel jagt mir überhaupt keine Angst ein.\n\nVielleicht können wir morgen wieder auf die Jagd gehen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39586] = { id = 39586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwingt sie in die Knie", description = "Seitdem wir sie bei der Schwarzfelsgießerei gedemütigt haben, ist die Eiserne Horde auf der Flucht. Gul'dan verwandelt alle in Höllenorcs, aber ich habe keine Angst. Ein Orc im Kampfrausch ist zweimal so stark, aber auch zweimal so dumm.\n\nHe! Schlagen wir uns zu den Schlachtfeldern von Tanaan durch und vernichten wir so viele Orcs, wie wir können. Orc oder Höllenorcs... Mir ist das egal.", sourceObjective = "Tötet 25 Orcs der Eisernen Horde im Tanaandschungel.", completion = "<Ihr und Parvink vergleicht die Geschichten Eurer Kämpfe im Dschungel. Am Ende brüllt sie:>\n\nRUHM DER ALLIANZ!!\n\n<... und zwar laut genug, um die Vögel in den Bäumen aufzuschrecken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[39588] = { id = 39588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie werden mit Blut bezahlen", description = "Die Tauren gehen zu weit. Ich bin nicht aus ihrem Außenposten geflohen, da ich befürchtete, sie würden die Höhle angreifen und meinen Stamm töten.\n\nEs sieht so aus, als hätten sie das die ganze Zeit geplant. Tötet einige der Teufelstotems. Dünnt die Herde aus.", sourceObjective = "Tötet 10 Tauren der Teufelstotems.", completion = "Ihre Anzahl ist gesunken, doch sie bedrohen noch immer unsere Sicherheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[39590] = { id = 39590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Konkurrenz voraus", description = "Der Wächter Yotnar bewacht die Kammer und gilt als besonders wählerisch. Die Herausforderer kommen von nah und fern, um die Prüfungen zu bestehen, aber der Wächter gibt vor, sie nicht zu sehen.\n\nWenn Ihr seine Aufmerksamkeit erregen wollt, müsst Ihr beweisen, dass Ihr es wert seid, angesehen zu werden.\n\nEinige der Herausforderer warten im Lager im Tal des Schwertes auf eine Gelegenheit. Bringt Yotnar ihre Köpfe, damit er sie sich ansehen kann... und Euch.", sourceObjective = "Sammelt die Köpfe der Champions der Darmreißer, Trampelhufe und Teufelsskorn im Tal des Schwertes ein.", progress = "Was für ein herrlich ironisches Geschenk Ihr mir da bringt, Herausforderer.", completion = "Eine Schande, dass der erste würdige Herausforderer um die Aegis die Prüfungen so respektlos angegangen ist. Mit solcher Überheblichkeit gewinnt man nicht die Aegis, sondern wird von den Göttern für seine Arroganz gestraft.\n\nIhr allerdings scheint anders zu sein. Ihr habt bewiesen, dass Ihr ein würdiger Herausforderer seid.\n\nIch werde es Euch gestatten, Euch den Prüfungen zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39591] = { id = 39591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Prüfung der Tapferkeit", description = "Um die Aegis von Aggramar zu erlangen, muss ein Champion drei große Prüfungen bestehen, um dann durch die Pforte der Tapferkeit zu reiten und sich in einer glorreichen Schlacht zu beweisen. Hier findet Ihr das Wissen über die erforderlichen Prüfungen und die erste Herausforderung, der Ihr Euch stellen müsst.\n\nÜber uns, als Zierde der mittleren Ebene, findet Ihr das Archiv der Prüfung der Tapferkeit. Sucht es auf, um mehr darüber zu erfahren, wohin Euer Weg Euch führt.", sourceObjective = "Fahrt das Archivgerät hoch und seht Euch die holografische Aufzeichnung für die Prüfung der Tapferkeit auf der Terrasse der Behüter an.", completion = "Jetzt wisst Ihr, welche Aufgaben Euch erwarten.\n\nWollt Ihr dennoch fortfahren?", sourceObjectiveStatus = "unverified-source-field" }
quests[39592] = { id = 39592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Prüfung des Willens", description = "Auf dem höchsten Punkt der Ebene über Euch findet Ihr das Archivgerät für die Prüfung des Willens. Sucht es auf, um zu sehen, was Euch am Thorimshorn erwartet.\n\nUnd passt auf Euch auf, <Fremder/Fremde>. Dieser andere Kandidat, Skovald, hat viele Soldaten seiner Armee zurückgelassen, und sie werden Euch ganz sicher nicht wohlgesonnen sein.", sourceObjective = "Fahrt das Archivgerät hoch und seht Euch die holografische Aufzeichnung für die Prüfung des Willens auf der Terrasse der Hüter an.", completion = "Das Wissen, das Ihr Euch angeeignet habt, kann Euch als mächtiges Werkzeug gegen Eure Feinde dienen.\n\nVergesst das nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[39593] = { id = 39593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gespaltene Wächter", description = "Nachdem Euer Widersacher – der, den sie Skovald nennen – seine erste Prüfung abgelegt hatte, setzte er seine verderbten Kräfte ein, um meinen weltlichen Körper zu zerschmettern.\n\nIch kann es keinem Kandidaten gestatten, die Kammer zu betreten, solange ich nicht vollständig bin.\n\nSeine Truppen haben meine Bruchstücke sicher auf dem ganzen Plateau über uns verteilt, während sie es besudelten. Bringt sie mir zurück, sodass ich Euch ordnungsgemäß Eurer Prüfung unterziehen kann.", sourceObjective = "Sammelt die Bruchstücke des Körpers von Yotnar auf der Terrasse der Behüter ein.", progress = "Habt Ihr sie alle gefunden?", completion = "Wunderbar!\n\nEs tut so gut, wieder vollständig zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[39594] = { id = 39594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Prüfung der Macht", description = "Ich schulde Euch Dank dafür, dass ich jetzt wieder vollständig bin, <Fremder/Fremde>. Ihr seid dieser Prüfung zweifellos würdig.\n\nBetretet jetzt die Kammer. Dort findet Ihr das Archiv für Eure erste Prüfung.\n\nIch treffe Euch im Inneren.", sourceObjective = "Aktiviert das Archivgerät, um mehr über die Prüfung der Macht zu erfahren.", completion = "Die Prüfung ist vorbei und Ihr wart siegreich!\n\nIhr habt hier Großes vollbracht, doch Euer Ziel ist lange nicht erreicht. Auf dem Weg zur Aegis warten noch viele große Herausforderungen auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[39595] = { id = 39595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut und Gold", description = "Die im Tal des Schwertes wartenden Herausforderer haben Geschenke für den Wächter der Kammer mitgebracht. \n\nEs ist vielleicht eine gute Idee, einige davon an Euch zu nehmen, um Yotnar damit zu beeindrucken.", sourceObjective = "Sammelt 7 Tribute der Herausforderer im Tal des Schwertes.", progress = "Was habt Ihr mir da mitgebracht?\n\nDas ist wirklich eine große Ehre, Fremder.", completion = "Danke für diese Geschenke, Fremder. Ihr beweist großen Respekt vor den Prüfungen.\n\nIhr wisst, wie man sich ehrenvoll verhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[39596] = { id = 39596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Vale - Vignette: Perrexx - TRACKING - twh" }
quests[39597] = { id = 39597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen der Wächter", description = "Da Ihr die Prüfung der Macht bestanden habt, gewähre ich Euch den Segen der Wächter.\n\nZudem werde ich Euer Artefakt mit der Kraft des Kammerwächters versehen, damit Ihr in den weiteren Prüfungen bestehen könnt. Ich hoffe, dass es Euch von Nutzen sein wird.\n\nSprecht mich an, wenn Ihr bereit seid, dieses Geschenk zu empfangen.", sourceObjective = "Sprecht mit Yotnar, um den Segen der Wächter zu empfangen.", completion = "Die Prüfung ist vorbei und Ihr seid immer noch am Leben. Dieses Land steckt voller Wunder, nicht wahr?\n\nUnd es scheint, als würde Euch der Gottkönig noch weitere Prüfungen auferlegen. Aber jetzt müsst Ihr Euch beeilen, denn die nächste Aufgabe erwartet Euch bereits!", sourceObjectiveStatus = "unverified-source-field" }
quests[39601] = { id = 39601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffer, versenkt!", description = "Kommandant, wir müssen unsere Flotte erweitern, wenn wir gegen die Eiserne Horde eine Chance haben wollen.\n\nWir haben Berichte aus Tanaan gehört, nach denen eine neue Allianzfraktion uns mit Plänen für den Bau von Schlachtschiffen versorgen kann. Macht Euch sobald Ihr könnt dorthin auf den Weg und untersucht das!", sourceObjective = "Trefft Verteidiger Krethos in der Löwenwacht im Tanaandschungel.", progress = "Hattet Ihr Glück mit diesen Schlachtschiffplänen?", completion = "Ich freue mich schon darauf, Eure beeindruckende Flotte aus Kriegsschiffen zu sehen, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[39602] = { id = 39602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Lyndras hin: Kanalerkundung", description = "Linzy hat gesagt, dass Lyndras in die Kanalisation von Dalaran geflüchtet ist. Bestimmt findet sich dort unten ein Hinweis auf seinen Aufenthaltsort.\n\nIch hoffe, er bereitet den Bürgern von Dalaran nicht noch mehr Unannehmlichkeiten.", sourceObjective = "Sucht die Kanalisation nach Hinweisen zu Lyndras' Verbleib ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[39604] = { id = 39604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treffer, versenkt!", description = "Kommandant, wir müssen unsere Flotte erweitern, wenn wir gegen die Eiserne Horde eine Chance haben wollen.\n\nWir haben Berichte aus Tanaan gehört, nach denen eine neue Hordefraktion uns mit Plänen für den Bau von Schlachtschiffen versorgen kann. Macht Euch sobald Ihr könnt dorthin auf den Weg und untersucht das!", sourceObjective = "Trefft Schattenjäger Denjai in Vol'mar im Tanaandschungel.", progress = "Hattet Ihr Glück mit diesen Schlachtschiffplänen?", completion = "Ich freue mich schon darauf, Eure beeindruckende Flotte aus Kriegsschiffen zu sehen, Kommandant.", sourceObjectiveStatus = "unverified-source-field" }
quests[39605] = { id = 39605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo ist Lyndras hin: Abwärtsspirale", description = "Flitz hat einen Kanalschacht in der Nähe der Violetten Festung erwähnt. Dort sollte man Lyndras' Spur am ehesten aufnehmen können.", sourceObjective = "Folgt weiter Lyndras' Spur.", completion = "Die Spur endet bei Linzys Leyflammenbrenner, der zerbrochen auf dem Boden liegt.\n\nIn der Nähe befinden sich jede Menge Wachen, die etwas bemerkt haben müssen. Vielleicht haben sie Lyndras gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39606] = { id = 39606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schätze Todesschwinges", description = "Neltharions Hort? Warum hat der Geistwandler das nicht gleich gesagt?\n\nAls wir in die Höhle sprangen, dachte ich, eine Kammer weit oben gesehen zu haben, die enthalten könnte, was wir suchen.\n\nSchaut Euch hier um, während ich nachsehe, was sich oben finden lässt.", sourceObjective = "Verteidigt Brann Bronzebart.", sourceObjectiveStatus = "unverified-source-field" }
quests[39607] = { id = 39607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "God-King Scene (Vault)" }
