quests[39614] = { id = 39614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fische an Land", description = "Die Drogbar sind in totale Zerstörungswut verfallen! Sie zerschmettern alles, was ihnen in die Quere kommt, und werfen Fische an Land.\n\nSchlimmer noch, es ist die falsche Zeit zum Fischfang. Die Tiere müssen zurück ins Wasser, damit sie laichen können.", sourceObjective = "Werft 8 Weißwasserkarpfen in den Fluss zurück.", completion = "Habt Dank. Ihr habt genug Fische gerettet, um eine neue Generation zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[39615] = { id = 39615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lights and Wreaths" }
